(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-async-rollout-pipeline"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-1\">一 · 一次版本标签错位的事故：异步流水线到底在解决什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-2\">二 · 机制：带版本号的队列与陈旧度自适应信任域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-3\">三 · 适用边界：长尾显著才值得，陈旧度上限由偏差容忍度决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-4\">四 · 不解决的问题与三类失败模式的工程归因</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-5\">五 · 与相邻算法的分工：时间维度 vs 数值维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-6\">六 · 异步流水线救不了的那类故障：长尾、版本漂移与队列饥饿</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-7\">七 · 版本化样本入队：从生成到落盘的第一跳</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-8\">八 · 训练侧取批：按步频消费与陈旧度记账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-9\">九 · 陈旧度缩放：重要性比与 KL 的双重约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-10\">十 · 权重同步：推送、原子切换与 KV 失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-11\">十一 · 水位反馈闭环：并发与步频的动态调节</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-12\">十二 · 陈旧度预算：从版本标签到可容忍滞后的工程边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-13\">十三 · 陈旧度缩放的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-14\">十四 · 吞吐公式与重叠因子的量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-15\">十五 · 伪代码：从入队到消费的可实现路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-16\">十六 · 失败模式的公式侧诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-17\">十七 · 与相邻机制的公式边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-18\">十八 · 调参旋钮的耦合关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-19\">十九 · 请求形态：持续流而非请求-响应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-20\">二十 · 批大小的两个约束源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-21\">二十一 · 并发：按陈旧度而非按利用率调</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-22\">二十二 · 负载不对时的三种典型失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-23\">二十三 · 配方与硬件档位的匹配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-24\">二十四 · 一个具体例子：模板短 prompt + 漂移生成长度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-25\">二十五 · 负载配方：什么样的请求形态才配得上这条流水线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-26\">二十六 · 硬件档位的匹配原则：按吞吐比而非按峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-27\">二十七 · 并行拓扑：训练侧张量并行、rollout 侧数据并行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-28\">二十八 · 量化方案：rollout 用 NVFP4/FP8，训练侧保持高精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-29\">二十九 · KV 策略：随版本失效重建与跨版本复用边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-30\">三十 · 调度参数：队列水位、陈旧度上限与并发联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-31\">三十一 · 可复现的配置思路：从吞吐账到参数表的落地顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-32\">三十二 · 显存：版本切换把 KV 变成一次性资产</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-33\">三十三 · 带宽：权重同步是异步流水线的隐性税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-34\">三十四 · 通信：尾延迟在异步下换了形态但没消失</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-35\">三十五 · 功耗与吞吐：overlap 不等于免费</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-36\">三十六 · 规模上去以后哪里先崩：三个阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-37\">三十七 · 工程判断：把尾延迟当一等指标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-38\">三十八 · 规模放大后的四道墙：带宽、显存、尾延迟与功耗</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-39\">三十九 · 陈旧度漂移：从统计量到可观测信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-40\">四十 · 精度异常：NVFP4 与异步叠加的隐蔽退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-41\">四十一 · OOM 与批抖动：队列水位与显存的双向耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-42\">四十二 · 路由不均与尾延迟尖刺：调度器的反馈滞后</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-43\">四十三 · 回滚策略：版本原子性与检查点粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-44\">四十四 · 陈旧度失控、版本混杂与队列失配：异步流水线的三类硬失效与观测回滚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-45\">四十五 · 同族谱系：把十几种 Rollout 算法放到同一张坐标系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-46\">四十六 · 决策表：六个判据与对应选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-47\">四十七 · 定量判据：用公式把&quot;选不选异步&quot;算出来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-48\">四十八 · 具体例子：一条长尾显著的 Agent rollout 如何选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-49\">四十九 · 混合与回退：什么时候不该选异步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-50\">五十 · 选型的工程落点：把判据写进调度器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-pipeline-sec-51\">五十一 · 陈旧度信任域的边界：何时该退回同步</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:536px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 536.1 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"454.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">rollout引擎用当前权重版本v生成样本，写入带版本号的样本队列</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"454.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">训练侧每步从队列取一批样本，记录其生成版本与当前版本的差距k</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"454.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按陈旧度k缩放重要性比与KL惩罚，限制过期样本对策略的拉扯</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"454.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">训练产出新权重v+1，经权重同步通道推送到rollout引擎，原子切换</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"454.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">队列水位与陈旧度分布反馈给调度器，动态调节rollout并发与训练步频</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-async-rollout-pipeline-sec-1\">一 · 一次版本标签错位的事故：异步流水线到底在解决什么</h3>\n\n<p>某 RL 训练集群在一次扩缩容后出现典型故障：rollout 引擎按 8 个实例持续生成，训练侧按固定步频消费，队列水位一度稳定。运维把 rollout 并发从 8 调到 12 以“喂饱”训练侧，但权重同步通道的推送节奏没有跟着改。结果在版本切换的瞬间，部分 rollout 实例已经加载新权重 <em>v+1</em>，另一部分仍在旧权重 <em>v</em> 上生成，而队列里的样本版本号是按“推送完成时刻”打标的，不是按“实际生成权重”打标的。训练侧取到一批标签为 <em>v+1</em>、实际由 <em>v</em> 生成的样本，计算出的重要性比与真实偏差方向相反，KL 惩罚被系统性低估。训练损失在若干步内先降后剧烈震荡，最终触发梯度裁剪与回滚。这次事故的根因不在算子、不在精度，而在**时间维度的版本一致性**——这正是异步 Rollout 流水线要处理的问题域。</p>\n\n<p>先把问题边界划清楚。同步 RL 的流程是 rollout 与训练串行：采样阶段全部结束、样本齐备，训练才开始；训练产出新权重，再进入下一轮采样。这个结构以串行换取严格 on-policy，代价是采样阶段的长尾样本决定整个迭代的 wall-clock。生成任务（尤其是带工具调用、多轮推理、变长输出的 agent 形态）的完成时间分布是重尾的：多数样本很快结束，少数样本拖到数倍于中位数的时长。GPU 在等待这批长尾样本时处于空转，算力利用率被长尾分布拉低，训练迭代被采样阶段主导。</p>\n\n<div class=\"formula\">$$\\text{throughput} \\approx \\frac{N_{\\text{rollout}}}{T_{\\text{rollout}}/\\text{overlap}+T_{\\text{train}}}$$</div>\n\n<p>上式给出异步的收益结构：分母中 <em>T</em><sub>rollout</sub> 被 overlap 因子折减，只要重叠有效，单位 wall-clock 内消费的样本数上升。但分子 <em>N</em><sub>rollout</sub> 不是免费的——它受队列水位、陈旧度上限与权重同步带宽三重约束。异步流水线**解决**的是“长尾样本阻塞训练步”这一具体问题；它**不解决**单样本生成太慢、单卡算力不足、KV cache 容量不够、通信拓扑瓶颈这些别的问题，也不解决数值精度稳定性（那是 NVFP4/FP8 稳定化条目的事），更不解决批组成不变性（那是批不变采样条目的事，处理的是数值维度的批组成而非时间维度的版本滞后）。把异步当成“通用加速开关”是误用。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-2\">二 · 机制：带版本号的队列与陈旧度自适应信任域</h3>\n\n<p>机制按数据流顺序展开。rollout 引擎用当前权重版本 <em>v</em> 生成样本，写入带版本号的样本队列；训练侧每步从队列取一批样本，记录其生成版本与当前版本的差距 <em>k</em>；按陈旧度 <em>k</em> 缩放重要性比与 KL 惩罚，限制过期样本对策略的拉扯；训练产出新权重 <em>v+1</em>，经权重同步通道推送到 rollout 引擎并原子切换；队列水位与陈旧度分布反馈给调度器，动态调节 rollout 并发与训练步频。</p>\n\n<p>核心是陈旧度自适应信任域。设样本由版本 <em>v−k</em> 生成，当前策略为 <em>θ</em>，则经缩放的重要性比为：</p>\n\n<div class=\"formula\">$$r_k=\\left(\\frac{\\pi_{\\theta}(x)}{\\pi_{\\theta_{v-k}}(x)}\\right)^{1/(1+\\beta k)},\\quad \\mathcal{L}_{\\text{KL}}=\\beta k\\,\\mathrm{KL}(\\pi_{\\theta}\\|\\pi_{\\text{ref}})$$</div>\n\n<p>指数 <em>1/(1+βk)</em> 的作用是把陈旧样本的重要性比压向 1：<em>k</em> 越大，该样本对策略更新的发言权越小，避免过期样本把策略拉向旧版本方向。KL 项随 <em>k</em> 线性加罚，进一步约束偏离参考策略的幅度。<em>β</em> 是陈旧度惩罚强度，它必须与 <em>k</em> 的上限联动——事故中的失败模式正是“陈旧度过大而 <em>β</em> 未同步增大”。伪代码思路：</p>\n\n<ul>\n<li>训练步开始，从队列取 batch，读每个样本的 <code>gen_version</code>，计算 <code>k = cur_version - gen_version</code>；</li>\n<li>按 <code>k</code> 计算 <code>r_k</code> 与 KL 权重，若 <code>k &gt; k_max</code> 则丢弃或降权该样本；</li>\n<li>反向传播后产出 <code>v+1</code>，通过同步通道推送，rollout 侧原子切换后才允许新样本打 <code>v+1</code> 标签；</li>\n<li>把队列水位与 <code>k</code> 分布回传调度器，调整 rollout 并发与训练步频。</li>\n</ul>\n\n<p>系统代价要算清楚。延迟侧：训练步不再等待长尾样本，单步 wall-clock 由“取队列 + 前反向”决定，但队列饥饿时训练侧空转，这是新的延迟来源。吞吐侧：重叠带来提升，但被陈旧度上限截断——<em>k</em> 上限越低，可用的滞后窗口越窄，重叠收益越小。显存侧：队列积压意味着样本驻留内存，水位越高驻留越多；同时权重版本切换会使 rollout 侧的 KV cache 失效重建，切换越频繁重建开销越大。带宽侧：权重同步通道占用 NVLink/NCCL 带宽，规模受权重同步带宽约束，rollout 实例越多、推送越频繁，同步开销越不可忽略。功耗侧：rollout 与训练同时满载，整机功耗抬升，机架供电与散热预算要按重叠态而非串行态规划。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-3\">三 · 适用边界：长尾显著才值得，陈旧度上限由偏差容忍度决定</h3>\n\n<p>适用条件可以写成三条判据。第一，rollout 长尾显著且采样阶段占主导——若单样本生成时长分布接近窄分布，串行损失本来就小，异步的复杂度不划算。第二，策略改进方向对滞后有容忍度——<em>k</em> 的上限由可容忍的偏差决定，过大时需回退同步或增大 <em>β</em>。第三，权重同步带宽与队列管理成本可控——系统复杂度随队列与版本管理上升，实例规模受同步通道带宽约束。</p>\n\n<table class=\"mini\"><thead><tr><th>场景特征</th><th>异步流水线是否适用</th><th>理由</th></tr></thead><tbody><tr><td>agent 多轮、工具调用、变长输出，长尾明显</td><td>适用</td><td>长尾样本不再阻塞训练步，重叠收益大</td></tr><tr><td>短输出、时长分布窄</td><td>不适用</td><td>串行损失小，队列与版本管理成本占比高</td></tr><tr><td>策略对滞后极敏感（强 on-policy 需求）</td><td>不适用或需极小 <em>k</em></td><td>陈旧度上限压缩重叠窗口，收益趋零</td></tr><tr><td>rollout 实例多、权重推送频繁</td><td>受限</td><td>同步带宽成为规模上限</td></tr></tbody></table>\n\n<p>具体例子：一个带检索工具的 agent 任务，多数样本 2–3 轮结束，少数样本因工具超时拖到十几轮。同步模式下训练步等这批长尾，GPU 空转；异步模式下训练侧按步频消费已完成的样本，长尾样本在后续版本被消费时按 <em>k</em> 降权。若把 <em>k</em> 上限设为很小以追求近似 on-policy，重叠窗口被压窄，长尾样本大概率被丢弃，等于把异步退化成“带丢弃的同步”，收益与复杂度不匹配。这就是边界的工程含义：**异步的收益与陈旧度容忍度成正比，与同步带宽成反比**。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-4\">四 · 不解决的问题与三类失败模式的工程归因</h3>\n\n<p>明确不解决什么同样重要。异步流水线不改变单样本生成的计算量，不减少 KV cache 占用，不提升 MMA 吞吐，不替代分页 KV 管理、分块预填、预填解码分离这些显存与调度手段；它也不处理数值精度引起的训练不稳定。它只处理“时间维度上采样与训练的重叠”以及由此产生的版本滞后偏差。</p>\n\n<p>三类失败模式都要能归因到具体机制。其一，样本陈旧度过大而 <em>β</em> 未同步增大：过期样本把策略拉向旧版本方向，训练震荡或崩溃。归因是信任域参数与队列水位脱钩，调度器只调并发不调 <em>β</em>。其二，权重同步通道在版本切换瞬间未原子化：rollout 引擎混用新旧权重，队列样本版本标签与实际生成权重不符——这正是开头事故的形态。归因是切换协议缺少“切换完成屏障”，标签打点时机错误。其三，队列水位反馈滞后于训练步频变化：rollout 并发与训练消费节奏失配，出现队列积压或训练侧饥饿空转。归因是反馈环路的控制周期长于步频变化周期。</p>\n\n<p>对应的工程判断：<em>k</em> 上限、<em>β</em>、并发、步频这四个量必须作为一组联合调节，任何一个单独动都会破坏平衡；版本切换必须原子化并有可观测的切换屏障；队列水位与 <em>k</em> 分布要作为一等指标上报，而不是事后从日志里翻。规模上限由权重同步带宽决定，当推送开销占迭代 wall-clock 的比例上升到不可忽略时，增加 rollout 实例不再带来净收益。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-5\">五 · 与相邻算法的分工：时间维度 vs 数值维度</h3>\n\n<p>与相邻算法的差别要一句话说清，避免与同模块其他条目重复。同步 RL 以串行换取严格 on-policy，wall-clock 被长尾样本主导；异步流水线以样本滞后换取时间重叠，并用陈旧度自适应约束偏差。与批不变采样不同，它处理的是时间维度的版本滞后而非数值维度的批组成；与分页 KV 批量 Rollout、分块预填背驮解码、预填解码分离 Rollout 等条目处理的是显存与调度形态不同，本条目只关心版本与队列；与特征级投机采样、NVFP4 量化稳定化处理的精度与接受率问题正交。KV 中心分离式池化解决的是缓存复用，不解决版本一致性；权重版本切换导致 KV cache 失效重建，是异步流水线自身的代价，需要与池化策略协同设计。</p>\n\n<p>落到具体机制上：当 rollout 与训练解耦部署、权重经同步通道推送时，KV cache 随版本切换失效重建是不可避免的，重建开销与切换频率成正比。工程上要么降低切换频率（增大每版本消费的样本量），要么让池化层按版本分区管理缓存，避免整池失效。这一步的判断依据是队列水位与 <em>k</em> 分布的实测形态，而不是架构图上的箭头。</p>\n\n\n<h3 id=\"alg-async-rollout-pipeline-sec-6\">六 · 异步流水线救不了的那类故障：长尾、版本漂移与队列饥饿</h3>\n<p>先把边界说清楚：异步 Rollout 流水线解决的是「时间维度上的串行等待」，不是「采样本身太慢」。线上最典型的事故形态是这样的：一个 RL 迭代里，绝大多数 rollout 请求在很短时间内返回，但每个 batch 总有少量长尾样本——超长序列、反复重试的工具调用、被限流的推理后端——把整个 batch 的完成时间拖到数倍于中位数。同步实现下，训练侧必须等这一批全部到齐才能前进一步，于是 GPU 在等待窗口里空转，迭代 wall-clock 被采样阶段主导。异步流水线把这段等待拆掉：rollout 引擎用权重版本 $v$ 持续生成并写入带版本号的队列，训练侧按固定节奏消费，样本允许滞后若干版本，用陈旧度 $k$ 缩放重要性比与 KL 惩罚。吞吐的粗略刻画是 <span class=\"formula\">$$\\text{throughput} \\approx \\frac{N_{\\text{rollout}}}{T_{\\text{rollout}}/\\text{overlap}+T_{\\text{train}}}$$</span> 关键在于分母里 rollout 时间被 overlap 除，而不是与训练时间相加——这正是它换来的东西。</p>\n<p>但它换来的东西有明确的价格，且价格不在「算法好不好」，而在「陈旧度分布是否可控」。失效条件之一是陈旧度过大而 $\\beta$ 未同步增大：过期样本把策略拉向旧版本方向，训练出现震荡甚至崩溃。此时 $r_k=\\left(\\pi_{\\theta}(x)/\\pi_{\\theta_{v-k}}(x)\\right)^{1/(1+\\beta k)}$ 的缩放不足以抵消分布偏移，$\\mathcal{L}_{\\text{KL}}=\\beta k\\,\\mathrm{KL}(\\pi_{\\theta}\\|\\pi_{\\text{ref}})$ 也只是软约束。第二个失效条件是权重同步通道未原子化：版本切换瞬间 rollout 引擎混用新旧权重，队列中样本的版本标签与实际生成权重不符，训练侧据此计算的 $k$ 是错的，信任域缩放的依据直接失真。第三个是反馈滞后：队列水位与陈旧度分布回传给调度器有延迟，rollout 并发与训练步频失配，出现队列积压（显存被样本与 KV cache 挤占）或训练侧饥饿空转（GPU 利用率掉回同步实现的水平）。</p>\n<p>系统代价要按资源分别记：延迟上，单样本端到端时延不再是优化目标，SLO 改为训练迭代 wall-clock 与陈旧度分布；显存上，队列积压直接吃掉本可给 KV cache 的容量，且权重版本切换会使在飞请求的 KV cache 失效重建，切换越频繁重建开销越大；带宽上，规模上限受权重同步通道约束——rollout 与训练解耦部署后，每次版本推进都要把整份权重推过同步通道，集群越大这笔开销越不可忽略。适用边界因此可以写成一句工程判断：适合 rollout 长尾显著、采样阶段占主导的 RL 训练；$k$ 的上限由策略改进方向可容忍的偏差决定，越界就回退同步或增大 $\\beta$；而若采样慢是均匀的、没有长尾，异步只增加队列与版本管理复杂度而不带来重叠收益。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>代价落点</th><th>处置</th></tr></thead><tbody><tr><td>陈旧度过大、$\\beta$ 未跟上</td><td>陈旧度分布右尾拉长、策略震荡</td><td>训练稳定性</td><td>增大 $\\beta$ 或回退同步</td></tr><tr><td>版本切换非原子</td><td>样本版本标签与实际权重不符</td><td>信任域计算失真</td><td>原子切换 + 版本校验</td></tr><tr><td>水位反馈滞后</td><td>队列积压或训练侧饥饿</td><td>显存 / GPU 利用率</td><td>缩短反馈环、限流并发</td></tr></tbody></table>\n<h3 id=\"alg-async-rollout-pipeline-sec-7\">七 · 版本化样本入队：从生成到落盘的第一跳</h3>\n<p>异步流水线的第一步不是“生成一个 batch”，而是“生成一个带版本号的样本”。rollout 引擎持有当前权重版本 $v$，按持续流的方式接受请求：每条请求进来后走预填、解码、采样，产出的 token 序列连同 prompt、logprob、采样温度、生成时刻一并封装成一条样本记录，记录头部写入 <code>gen_version = v</code>。这一步的输入是请求队列与权重版本号，输出是带版本标签的样本记录，代价集中在解码阶段的显存带宽与 KV cache 占用——rollout 引擎的吞吐上限由 decode 的 memory-bound 特性决定，而非算力。</p>\n<p>关键工程点在于版本标签的写入时机。标签必须在采样动作发生的同一原子上下文里打上，不能在样本落盘后再补写，否则权重切换窗口内的样本会被错标。伪代码思路是：</p>\n<div class=\"formula\">$$\\text{sample} \\rightarrow (\\text{tokens}, \\log\\pi_{v}, v) \\rightarrow \\text{enqueue}(\\text{queue}_v)$$</div>\n<p>队列按版本分桶，桶内按到达顺序排列。分桶而非单一 FIFO 的理由是训练侧取样本时要按版本聚合，单一队列会让版本混杂的样本在出队时被迫重排，增加调度器负担。代价是队列元数据显存随版本数线性增长，版本保留窗口需要显式上限，否则长尾样本堆积会把队列撑爆。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-8\">八 · 训练侧取批：按步频消费与陈旧度记账</h3>\n<p>训练侧按固定节奏消费：每完成一次参数更新算一步，每步从队列取一批样本。取批策略不是“取最新”，而是“取足够新且足够满”。调度器先看队列水位，再看各版本桶的样本数，凑出一个满足批大小的组合，同时记录每条样本的生成版本与当前训练版本的差距 $k = v_{\\text{cur}} - v_{\\text{gen}}$。这一步的输入是队列状态与当前版本号，输出是一个带 $k$ 标签的训练 batch，代价是取批逻辑本身几乎不耗算力，但它决定了后续重要性比缩放的分布形状。</p>\n<p>记账的粒度决定偏差控制的精度。按 batch 记一个平均 $k$ 会让长尾样本的极端陈旧度被平均掉，按样本记 $k$ 则让每条样本各自缩放，代价是逐样本的缩放因子要进 kernel，增加一点寄存器压力。工程上通常取折中：桶内按 $k$ 分档，同档样本共享缩放因子，档数控制在个位数，既保留分辨率又不炸 kernel 参数。</p>\n<p>这一步的系统代价体现在训练侧的空转风险：队列水位低于批大小时训练步被迫等待，等待时长直接进 wall-clock。水位反馈滞后于步频变化时，rollout 并发调高但训练侧消费不过来，队列积压；反之训练侧饥饿。两种失配都表现为 GPU 利用率曲线上的锯齿。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-9\">九 · 陈旧度缩放：重要性比与 KL 的双重约束</h3>\n<p>拿到带 $k$ 的 batch 后，训练侧计算重要性比。朴素的重要性比 $\\pi_\\theta/\\pi_{\\theta_{\\text{old}}}$ 在异步场景下分母是旧版本，分子是新版本，比值方差随 $k$ 增大而爆炸。陈旧度自适应信任域的做法是把比值开方缩放：</p>\n<div class=\"formula\">$$r_k=\\left(\\frac{\\pi_{\\theta}(x)}{\\pi_{\\theta_{v-k}}(x)}\\right)^{1/(1+\\beta k)},\\quad \\mathcal{L}_{\\text{KL}}=\\beta k\\,\\mathrm{KL}(\\pi_{\\theta}\\|\\pi_{\\text{ref}})$$</div>\n<p>指数 $1/(1+\\beta k)$ 的作用是把比值往 1 拉：$k$ 越大，缩放越狠，过期样本对策略的拉扯越弱。KL 惩罚项同时乘 $\\beta k$，让陈旧样本在正则层面也被压制。这一步的输入是 batch 的 logprob 与 $k$ 标签，输出是缩放后的损失，代价是每个 token 多一次幂运算与一次 KL 计算——相对前向反向的矩阵乘可以忽略，但幂运算在 FP8 路径上要小心数值范围，指数缩放后的比值可能落到低精度表示的死区。</p>\n<p>$\\beta$ 的选择是纯工程判断：$\\beta$ 太小，$k$ 大时缩放不足，策略被旧方向拉走；$\\beta$ 太大，新样本也被过度压制，策略改进变慢。失败模式很明确——样本陈旧度过大而 $\\beta$ 未同步增大，过期样本把策略拉向旧版本方向，训练震荡或崩溃。$\\beta$ 应随队列的 $k$ 分布自适应，而不是固定常数。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-10\">十 · 权重同步：推送、原子切换与 KV 失效</h3>\n<p>训练产出新权重 $v+1$ 后，经同步通道推送到 rollout 引擎。这一步的输入是新权重张量，输出是 rollout 引擎上生效的权重版本，代价是权重同步带宽——大模型权重动辄数十 GB，跨节点推送要走 NVLink 或 RDMA，同步窗口内 rollout 引擎要么暂停生成要么继续用旧权重。暂停则损失吞吐，继续则产生版本混杂。</p>\n<p>原子切换是这一步的核心机制。切换必须保证“新请求用新权重、在途请求用旧权重、样本标签与实际权重一致”。实现上通常用双缓冲：新权重写入影子缓冲，切换指针的瞬间完成生效，在途请求持有的旧缓冲引用计数归零后释放。切换瞬间的样本版本混杂是已知失败模式——权重同步通道未原子化时，rollout 引擎混用新旧权重，队列中样本版本标签与实际生成权重不符，后续 $k$ 记账全部失真。</p>\n<p>KV cache 随权重版本切换而失效重建。这是常被低估的代价：切换后所有前缀 KV 都要重算，预填成本在切换点集中爆发。若切换频繁，KV 重建的算力开销会吃掉异步带来的重叠收益。工程判断是切换频率要与权重更新幅度匹配——小步更新可以拉长切换间隔，大步更新则必须切。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-11\">十一 · 水位反馈闭环：并发与步频的动态调节</h3>\n<p>最后一步是把队列水位与陈旧度分布反馈给调度器。输入是队列各版本桶的深度、$k$ 的分布直方图、训练侧步频，输出是 rollout 并发上限与训练步频的调整量。这一步不产生样本也不产生梯度，但它决定整条流水线是否稳态。</p>\n<p>反馈逻辑的伪代码思路是：队列水位高于高水位线则降 rollout 并发或提训练步频；水位低于低水位线则反向调节；$k$ 分布右尾过厚则提 $\\beta$ 或降并发。代价是反馈环路的延迟——调度决策到实际生效之间有若干步的滞后，滞后期间水位继续漂移。反馈滞后于训练步频变化是典型失配：rollout 并发与训练消费节奏失配，出现队列积压或训练侧饥饿空转。</p>\n<p>吞吐的粗略关系是 throughput ≈ N_rollout / (T_rollout/overlap + T_train)，overlap 项就是这条反馈环路能压榨出的时间重叠比例。水位反馈的作用是让 overlap 尽量接近 1 而不让 $k$ 失控。规模上限受权重同步带宽约束：同步通道越窄，切换越慢，可容忍的切换频率越低，异步的重叠收益越难兑现。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>版本化入队</td><td>请求流、权重 $v$</td><td>带 gen_version 的样本</td><td>decode 显存带宽、KV 占用</td></tr><tr><td>训练侧取批</td><td>队列状态、当前版本</td><td>带 $k$ 标签的 batch</td><td>取批延迟、空转风险</td></tr><tr><td>陈旧度缩放</td><td>logprob、$k$</td><td>缩放后损失</td><td>逐 token 幂运算、FP8 数值范围</td></tr><tr><td>权重同步</td><td>新权重张量</td><td>生效版本 $v+1$</td><td>同步带宽、KV 重建算力</td></tr><tr><td>水位反馈</td><td>水位、$k$ 分布</td><td>并发与步频调整量</td><td>反馈滞后、稳态漂移</td></tr></tbody></table>\n<p>五个步骤串起来看，异步流水线的稳态不是靠单点优化，而是靠版本标签、$k$ 记账、原子切换三者的一致性。任何一环的标签失真都会让陈旧度缩放失去依据，策略改进方向随之失真。工程上最该盯的不是吞吐曲线，而是队列中样本版本标签与实际生成权重的偏差率——这个指标一旦非零，后面所有缩放都是错的。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-12\">十二 · 陈旧度预算：从版本标签到可容忍滞后的工程边界</h3>\n<p>把流水线拆成“生成—入队—消费—缩放—回推—反馈”六步之后，真正决定这套方案能不能上生产的不是重叠本身，而是每一步的<strong>版本语义是否可信</strong>。第一步 rollout 引擎以权重版本 v 生成 token 序列，输出是（样本, v）二元组，代价是持续占用 rollout GPU 与 KV cache；第二步写入带版本号的队列，代价是主机侧队列内存与一次跨进程拷贝，队列深度直接决定后续可容忍的 k 上限。第三步训练侧取批并记录 k = v_now − v_sample，这一步的输入是队列水位与当前版本号，输出是本批的陈旧度直方图；第四步按 k 缩放重要性比与 KL 惩罚，代价是每 token 一次额外的比值计算与一次 KL 估计，属于纯算术开销，相对前向反向可忽略，但它决定了过期样本会不会把梯度方向拉偏。第五步训练产出 v+1 并经同步通道原子切换，代价是权重广播的带宽占用——在 NVL72 这类域内，权重推送与 rollout 的 KV cache 重建会同时发生，切换瞬间在途请求必须要么完成要么丢弃，否则队列里会出现版本标签与实际生成权重不符的样本。第六步把水位与陈旧度分布回馈调度器，代价是反馈环路的时延：反馈滞后于训练步频变化时，rollout 并发与消费节奏失配，表现为队列积压或训练侧饥饿空转。</p>\n<p>边界条件可以用一个预算不等式表达。设可容忍陈旧度上限为 K，单步训练消费样本数为 B，rollout 引擎在版本 v 下的有效吞吐为 R_v（样本/秒），则队列必须满足 <span class=\"formula\">$$K \\cdot B \\;\\le\\; \\rho_{\\text{buf}} \\cdot R_v \\cdot T_{\\text{step}}$$</span> 其中 ρ_buf 是允许的在途样本比例，T_step 是训练步周期。这个不等式说明：K 不是拍脑袋选的超参，而是由队列容量、rollout 吞吐与训练步频三者共同锁定的系统量。当 rollout 长尾使 R_v 抖动时，固定 K 会周期性违反不等式，此时要么扩大队列吸收抖动，要么让调度器按水位动态压低 K 并同步增大 β。反过来，若为了压 k 而把训练步频调慢，重叠收益被吃掉，wall-clock 又回到被采样主导的老路。因此 K 与 β 必须成对调节：β 太小而 k 变大，过期样本把策略拉向旧版本方向，训练震荡；β 随 k 线性增大则等价于给远版本样本近乎零权重，队列实际有效深度被压缩，吞吐回落。</p>\n<p>失效条件集中在三处，且都不是算法层面的，而是系统层面的。其一是<strong>版本切换非原子</strong>：权重推送与 rollout 引擎的权重加载若不在同一同步点完成，部分 worker 已用 v+1 生成而另一些仍用 v，队列中样本的版本标签与实际生成权重不符，重要性比的分母失真，缩放公式失去意义。工程上要求切换以请求为粒度生效——在途请求用旧权重跑完并打旧标签，新请求一律取新权重，切换窗口内不接受跨版本批混跑。其二是<strong>反馈滞后</strong>：水位采样周期若长于训练步周期，调度器看到的是过期水位，调节动作总是慢半拍，在负载突变时放大振荡。其三是<strong>KV cache 与版本绑定</strong>：权重切换使在途请求的 KV cache 失效重建，重建成本按序列长度与层数计，切换越频繁这部分开销占比越高，于是存在一个最优切换间隔，过短则重建开销吃掉重叠收益，过长则 k 逼近上限。三者叠加的系统代价是：重叠带来的 wall-clock 缩短被权重广播带宽、KV 重建与队列管理开销部分抵消，净收益随集群规模与模型宽度变化，规模上限由权重同步带宽而非算力决定。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>生成</td><td>权重 v、请求</td><td>(样本, v)</td><td>rollout GPU、KV cache</td></tr><tr><td>入队</td><td>样本、版本号</td><td>带版本队列</td><td>主机内存、拷贝</td></tr><tr><td>消费</td><td>队列水位、v_now</td><td>批 + 陈旧度 k</td><td>取批时延</td></tr><tr><td>缩放</td><td>k、β</td><td>r_k、KL 项</td><td>每 token 算术</td></tr><tr><td>回推</td><td>v+1</td><td>原子切换</td><td>权重广播带宽、KV 重建</td></tr><tr><td>反馈</td><td>水位、k 分布</td><td>并发与步频</td><td>反馈时延</td></tr></tbody></table>\n<p>一个具体的判断例子：当 rollout 长尾显著、采样阶段占训练 wall-clock 主导时，异步流水线的净收益取决于 T_rollout 中被重叠掉的比例是否大于权重切换与 KV 重建的固定开销；若模型极宽、权重广播耗时接近单步训练时间，则切换频率必须降到 k 上限附近，此时 β 需同步上调，否则过期样本主导梯度。反之，若 rollout 吞吐远高于训练消费速率，队列会持续积压，k 单调上升直到触及上限，调度器应优先压低 rollout 并发而不是加大队列——积压不是缓冲，是偏差的来源。这条判断线把“异步是否划算”从算法偏好问题转化为带宽与队列水位的可测量问题。</p>\n<h3 id=\"alg-async-rollout-pipeline-sec-13\">十三 · 陈旧度缩放的逐项拆解</h3>\n<p>本部分只做一件事：把异步 Rollout 流水线里那条信任域公式拆到每一项都能落到代码，并给出从“版本差”到“有效步长”的推导关键一步。先看形式：$$r_k=\\left(\\frac{\\pi_{\\theta}(x)}{\\pi_{\\theta_{v-k}}(x)}\\right)^{1/(1+\\beta k)},\\quad \\mathcal{L}_{\\text{KL}}=\\beta k\\,\\mathrm{KL}(\\pi_{\\theta}\\|\\pi_{\\text{ref}})$$ 其中 $x$ 是样本（状态-动作序列），$\\theta$ 是训练侧当前权重，$\\theta_{v-k}$ 是该样本被生成时的权重版本，$k$ 是版本差，$\\beta$ 是陈旧度惩罚强度。</p>\n<p>逐项解释。分子 $\\pi_\\theta(x)$ 是当前策略对整条样本序列的对数概率之和，训练侧前向即可得到；分母 $\\pi_{\\theta_{v-k}}(x)$ 是生成时策略的概率，这一项不能靠训练侧重算——重算需要旧权重，而旧权重在异步流水线里已被覆盖。工程上必须在 rollout 引擎生成样本时就把 $\\log\\pi_{\\theta_{v-k}}(x)$ 随 token 一起写入队列，训练侧直接读取，这是整个公式可实现的第一个前提。$k$ 不是标量常量，而是每个样本自带的标签：样本入队时写入 $v$，训练侧消费时用当前版本 $v_{\\text{cur}}$ 减去它。$\\beta$ 是超参，控制陈旧度对信任域的收紧速度。</p>\n<p>指数 $1/(1+\\beta k)$ 是核心。当 $k=0$ 时指数为 1，$r_k$ 退化为标准重要性比，等价于同步 on-policy；当 $k$ 增大，指数被压向 0，$r_k$ 被拉向 1。这一步的物理含义是：越陈旧的样本，其重要性比越被“压平”，对梯度方向的拉扯越弱。代价是梯度信号变钝——陈旧样本几乎不再贡献有效更新，只贡献一个被正则化的噪声项。因此 $\\beta$ 的选择直接决定吞吐与稳定性的折中点：$\\beta$ 偏小则陈旧样本仍在用力拉策略，$\\beta$ 偏大则队列里大部分样本沦为无效填充。</p>\n<p>推导的关键一步在于把“版本差”映射为“分布漂移上界”。设单步策略更新使 KL 增加 $\\delta$，则经过 $k$ 步版本演进，$\\mathrm{KL}(\\pi_{\\theta_{v-k}}\\|\\pi_\\theta)\\lesssim k\\delta$（三角不等式逐级累加）。若不加缩放，重要性比方差随 $k\\delta$ 指数增长，梯度估计的偏差不可控。把指数取为 $1/(1+\\beta k)$，等价于把有效学习率按 $1/(1+\\beta k)$ 衰减，使单样本对参数的贡献上界被 $\\beta k$ 线性压制，从而把 $k\\delta$ 的累积漂移折算回一个可控的信任域半径。这不是严格的理论界，而是工程上的单调收缩映射：$k$ 越大，收缩越强，且收缩强度与 $\\beta$ 线性相关，便于调参时用 $\\beta$ 单旋钮控制整条流水线的 off-policy 容忍度。</p>\n<p>KL 惩罚项 $\\beta k\\,\\mathrm{KL}(\\pi_\\theta\\|\\pi_{\\text{ref}})$ 与重要性比缩放是同一逻辑的两条腿：前者约束当前策略不要偏离参考策略太远，后者约束陈旧样本不要偏离当前策略太远。注意惩罚系数随 $k$ 线性增长，意味着一个批次里混有不同 $k$ 的样本时，KL 项必须按样本加权而非按批平均，否则陈旧样本的正则会被新样本稀释。具体代价：每样本多一次 $\\log\\pi_\\theta$ 前向与一次 KL 累加，相对整批前向可忽略；但若实现成按批标量 KL，则失去逐样本控制，失败模式正是“陈旧度过大而 $\\beta$ 未同步增大，过期样本把策略拉向旧版本方向”。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-14\">十四 · 吞吐公式与重叠因子的量化</h3>\n<p>第二条公式：$$\\text{throughput}\\approx\\frac{N_{\\text{rollout}}}{T_{\\text{rollout}}/\\text{overlap}+T_{\\text{train}}}$$ 分子 $N_{\\text{rollout}}$ 是一个训练迭代消费的样本数，分母是迭代 wall-clock。$T_{\\text{rollout}}$ 是纯采样耗时，$T_{\\text{train}}$ 是纯训练耗时，overlap 是重叠因子（0 到 1 之间，表示采样与训练真正并行的那部分比例）。同步 RL 中 overlap=0，分母为 $T_{\\text{rollout}}+T_{\\text{train}}$，wall-clock 被长尾样本主导；异步流水线把 overlap 推向 1，分母趋近 $\\max(T_{\\text{rollout}},T_{\\text{train}})$，理论加速比上限为 $(T_{\\text{rollout}}+T_{\\text{train}})/\\max(T_{\\text{rollout}},T_{\\text{train}})$。</p>\n<p>overlap 不是常数，它由队列水位与训练步频共同决定。设 rollout 引擎的稳态产出率为 $R$（样本/秒），训练侧消费率为 $C$，则队列水位 $Q(t)$ 的演化近似为 $\\mathrm{d}Q/\\mathrm{d}t=R-C$。当 $R&gt;C$ 队列积压，overlap 受限于训练侧消费能力，实际吞吐被 $T_{\\text{train}}$ 卡住；当 $R&lt;C$ 训练侧饥饿，overlap 受限于采样产出，实际吞吐被 $T_{\\text{rollout}}$ 卡住。理想工作点在 $R\\approx C$ 附近，此时队列水位小幅波动，overlap 接近 1。调度器要做的就是把 $R$ 与 $C$ 锁在这个窄带内——rollout 并发调 $R$，训练步频调 $C$。</p>\n<p>具体例子：若某迭代 $T_{\\text{rollout}}$ 因长尾样本被拉到 $T_{\\text{train}}$ 的数倍，同步模式下 wall-clock 几乎全花在等最后几条长样本；异步模式下这些长样本仍在生成，但训练侧已用队列中较早完成的样本推进了若干步，overlap 把长尾的等待摊到多个训练步上。代价是这些长样本入队时 $k$ 已经变大，必须靠第一节的 $\\beta k$ 收缩来兜底。也就是说，吞吐公式里的 overlap 与信任域公式里的 $k$ 是同一枚硬币的两面：overlap 越高，样本平均 $k$ 越大，$\\beta$ 必须相应上调，否则吞吐收益被稳定性问题吃掉。</p>\n<p>工程判断：overlap 的提升不是免费的。权重同步通道在每次版本切换时要推送整份权重到 rollout 引擎，同步带宽成为规模上限；KV cache 随权重版本切换而失效重建，切换瞬间的样本版本混杂会污染队列。因此吞吐公式应被读作“上界”，实际可达吞吐还要乘一个由同步开销与版本混杂率决定的折损因子。调度器在调并发时，必须同时监控队列水位与陈旧度分布两个信号，只盯水位会在版本切换瞬间误判。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-15\">十五 · 伪代码：从入队到消费的可实现路径</h3>\n<p>把两条公式落到代码，核心是三个数据结构：带版本标签的样本队列、每样本的旧策略对数概率、以及训练侧的版本计数器。伪代码思路如下（文字描述，不落 <pre>）：rollout 引擎侧循环执行“取当前权重版本 v → 生成一批样本 → 对每个 token 记录 $\\log\\pi_{\\theta_v}$ → 打包 (样本, v, logp_old) 入队”；训练侧循环执行“从队列取一批 → 对每样本算 $k=v_{\\text{cur}}-v_{\\text{sample}}$ → 用 $\\log\\pi_\\theta-\\text{logp\\_old}$ 乘 $1/(1+\\beta k)$ 得 $r_k$ → 加权损失反向 → 更新 $\\theta$ → $v_{\\text{cur}}{+}{+}$ → 经同步通道推送权重 → 原子切换”。</p>\n<p>关键实现细节有三处。第一，$r_k$ 的计算必须在 log 空间完成：$r_k=\\exp\\big((\\log\\pi_\\theta-\\text{logp\\_old})/(1+\\beta k)\\big)$，避免概率连乘下溢；对长序列，$\\log\\pi$ 是逐 token 求和，除以 $(1+\\beta k)$ 后再 exp，数值稳定性远好于先算比值再开方。第二，$k$ 的粒度是样本级而非批级：一个批次里可能混有 $k=0$ 到 $k=k_{\\max}$ 的样本，损失必须逐样本加权后求和，不能先平均再乘标量 $\\beta$。第三，权重同步必须原子化：rollout 引擎在切换瞬间要么全用旧权重、要么全用新权重，中间态会让队列里样本的版本标签与实际生成权重不符——这正是列出的失败模式之一。</p>\n<p>队列管理需要一个背压机制。当队列水位超过高水位线，rollout 引擎应降低并发或暂停入队；当水位低于低水位线，训练侧应降步频或等待。水位反馈滞后于训练步频变化会导致两种失配：队列积压（rollout 白烧算力）或训练侧饥饿空转（训练 GPU 等样本）。因此调度器应以陈旧度分布为主信号、水位为辅信号：陈旧度中位数上升说明消费跟不上产出，应先降 rollout 并发而非盲目加训练步频。</p>\n<p>系统代价核算：每样本多存一份 $\\log\\pi_{\\theta_v}$，按序列长度线性增长，是队列内存的主要开销；每步多一次逐样本 $k$ 计算与 log 空间缩放，相对前向可忽略；权重同步每次推送整份参数，带宽占用与模型规模成正比，是规模上限的硬约束。KV cache 在版本切换时失效重建，意味着 rollout 引擎的有效吞吐在切换瞬间有一个凹陷，调度器应避免在高水位时触发切换。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-16\">十六 · 失败模式的公式侧诊断</h3>\n<p>三条失败模式都能在公式里找到对应项。第一条“陈旧度过大而 $\\beta$ 未同步增大”：表现为 $r_k$ 的指数趋近 0 但 $\\beta k$ 项在 KL 惩罚里仍小，梯度被陈旧样本拉向旧版本方向，训练震荡。诊断信号是 $r_k$ 的方差随 $k$ 单调上升而非被压制——正常工作时 $r_k$ 应随 $k$ 增大而收敛到 1 附近，方差收缩；若方差反而扩大，说明 $\\beta$ 相对 $k$ 太小，应上调 $\\beta$ 或设 $k_{\\max}$ 硬截断，把超限样本丢弃或回退同步。</p>\n<p>第二条“版本切换未原子化”：表现为队列中样本的版本标签与实际生成权重不符，$\\text{logp\\_old}$ 与标签 $v$ 不一致，$k$ 被算错，$r_k$ 系统性偏移。诊断方法是抽样比对：对同一批样本用标签版本重算 $\\log\\pi$，与存储的 $\\text{logp\\_old}$ 比对，偏差超阈值即说明切换非原子。修复靠双缓冲权重槽加指针原子交换，rollout 引擎读指针而非读权重本体。</p>\n<p>第三条“水位反馈滞后”：表现为 $Q(t)$ 的振荡周期与训练步频变化周期错拍，$\\mathrm{d}Q/\\mathrm{d}t=R-C$ 的符号反复翻转，overlap 在 0 与 1 之间跳变，吞吐公式的分母忽大忽小。诊断信号是队列水位的自相关函数出现长周期振荡。修复靠把调度决策周期压到训练步频的若干分之一，并用陈旧度分布做前馈而非仅用滞后水位做反馈。</p>\n<p>三条失败模式的共同点是：公式本身没错，错在公式的输入（$k$、$\\beta$、$\\text{logp\\_old}$、$Q$）没有被正确测量或没有被正确耦合。因此工程上应把 $k$ 的分布、$r_k$ 的方差、水位振荡周期作为一等监控指标，与吞吐、wall-clock 并列上报，而不是等训练崩了再回头查。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-17\">十七 · 与相邻机制的公式边界</h3>\n<p>与批不变采样（batch-invariant sampling）的边界：后者处理的是数值维度——同一 token 在不同批组成下采样结果应一致，公式落在 logits 归约顺序与 kernel 确定性上；本流水线的 $r_k$ 处理的是时间维度——同一策略在不同版本下的概率比。两者正交，可以叠加：批不变保证 $r_k$ 的分子分母不受批组成扰动，陈旧度缩放保证时间滞后被约束。实现上若采样 kernel 非批不变，$r_k$ 会混入批组成噪声，被误读为陈旧度效应。</p>\n<p>与分离式预填/解码的边界：后者切分的是单次前向的计算阶段（预填与解码分到不同 GPU 池），优化的是单请求延迟与池利用率；本流水线切分的是训练与采样两条时间线，优化的是迭代 wall-clock。分离式部署里 rollout 引擎本身就是解耦的，权重同步通道与 KV 池化通道是两条独立链路，本流水线的公式只作用于样本队列与版本标签，不改变预填/解码的切分策略。</p>\n<p>与特征级投机采样的边界：投机采样在 token 维度用草稿模型加速单样本生成，改变的是 $T_{\\text{rollout}}$ 的分子项（每 token 成本）；本流水线改变的是 $T_{\\text{rollout}}$ 与 $T_{\\text{train}}$ 的重叠关系。两者可叠加：投机采样压低单样本生成延迟，使 rollout 产出率 $R$ 上升，队列更容易在高水位运行，此时 $\\beta$ 需随平均 $k$ 上调。注意投机采样的接受率若随权重版本漂移，会额外引入与 $k$ 耦合的偏差，需在 $\\text{logp\\_old}$ 里用实际接受路径的概率而非草稿概率。</p>\n<p>规模上限的公式侧表述：权重同步带宽 $B$ 与模型参数量 $P$ 决定单次切换耗时 $P/B$，切换频率受训练步频约束，故 $k_{\\max}$ 与 $P/B$ 成正比。当 $P$ 增大，同步变慢，$k$ 上限被动抬高，$\\beta$ 必须相应增大或回退同步。这是异步流水线在超大模型上的硬边界：不是算法不允许，而是同步通道的物理带宽把 $k$ 压不下去。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-18\">十八 · 调参旋钮的耦合关系</h3>\n<p>三个旋钮——$\\beta$、$k_{\\max}$、调度周期——不是独立的。$\\beta$ 控制收缩强度，$k_{\\max}$ 控制硬截断，调度周期控制 $R$ 与 $C$ 的匹配速度。给定目标吞吐，$\\beta$ 的下界由平均 $k$ 决定：平均 $k$ 越大，$\\beta$ 必须越大才能把 $r_k$ 方差压住；$\\beta$ 的上界由有效样本率决定：$\\beta$ 太大则大量陈旧样本的梯度贡献趋零，等效于浪费队列算力，$N_{\\text{rollout}}$ 的有效值下降。工程上应先测 $k$ 的稳态分布，再定 $\\beta$ 使 $r_k$ 方差落在可接受带内，最后用 $k_{\\max}$ 兜底极端长尾。</p>\n<p>调度周期与 $\\beta$ 的耦合体现在版本切换瞬间：切换时 $k$ 分布整体跳变，若调度周期长于切换间隔，$\\beta$ 来不及跟随，会出现短暂的陈旧样本过权。缓解办法是在切换窗口内临时提高 $\\beta$ 或暂停消费高 $k$ 样本，等队列换血后再恢复。这一窗口的长度由 $P/B$ 与队列深度共同决定，是部署配方里必须显式配置的参数，而非隐式默认。</p>\n<p>最后落到一个具体判断：当 rollout 长尾显著、采样阶段占主导时，异步流水线的收益来自 overlap 把长尾等待摊薄；但收益能否兑现，取决于 $\\beta k$ 是否把陈旧样本的拉扯压到策略改进方向可容忍的范围内。若监控显示 $r_k$ 方差随 $k$ 不收敛，或队列水位振荡周期与步频错拍，正确动作是回退同步或增大 $\\beta$ 并设 $k_{\\max}$，而不是继续加 rollout 并发——后者只会把更多陈旧样本灌进队列，让公式里的收缩项疲于奔命。</p>\n</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-19\">十九 · 请求形态：持续流而非请求-响应</h3>\n<p>异步 Rollout 流水线的负载不是在线服务意义上的“请求-响应”，而是一条由训练步频反向定速的持续生成流。rollout 引擎侧没有外部用户到达过程，它的“到达率”由调度器根据队列水位与陈旧度分布反推出来：训练侧每步需要 $B_{\\text{train}}$ 条样本，rollout 侧必须以不低于该消费速率的有效产出维持队列不空。因此负载配方的第一项不是 QPS，而是<b>生成速率与消费速率的匹配关系</b>。把这条流水线当成推理服务来压测——按泊松到达、按 P99 延迟设 SLO——会直接错配：这里没有尾延迟意义上的用户，只有队列水位意义上的饥饿与积压。</p>\n<p>请求形态的第二个特征是<b>长度分布的双峰性</b>。RL 样本的 prompt 往往来自固定任务模板（短而齐），而生成侧的长度由策略自身决定，在探索早期方差极大，在策略收敛后迅速收窄。这意味着 rollout 引擎面对的 decode 长度分布不是静态的，而是随训练进程漂移的。分页 KV 与连续批处理能吸收这种漂移，但前提是调度器把长度分布当作可观测量而非常量。工程上应把 rollout 侧的长度直方图作为调度输入之一，与队列水位并列。</p>\n<p>第三个特征是<b>版本标签的强绑定</b>。每条样本必须携带生成时的权重版本 $v$，因为下游训练要据此计算陈旧度 $k$。这使负载配方多了一个维度：不仅要有足够的样本，还要有足够“新鲜”的样本。队列里堆满 $k$ 很大的样本，等价于没有样本——它们要么被 $\\beta k$ 的 KL 惩罚压到近乎无效，要么把策略拉向旧方向。所以负载配方的正确表述是：<b>在给定陈旧度分布约束下的有效样本吞吐</b>，而不是裸样本吞吐。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-20\">二十 · 批大小的两个约束源</h3>\n<p>批大小在这条流水线上不是自由参数，它被两个方向同时夹住。向上，训练侧的批大小 $B_{\\text{train}}$ 由优化器与梯度方差决定，属于算法侧给定；向下，rollout 引擎的 micro-batch 由显存与 decode 的 KV 占用决定。中间的调度自由度是<b>队列深度</b>：队列里常驻多少个版本的样本、每个版本多少条。</p>\n<p>队列深度与陈旧度上限 $k_{\\max}$ 是同一个量的两种写法。若 rollout 产出速率为 $R$（样本/秒），训练消费速率为 $C$，则稳态队列长度约正比于 $R/C$ 的失配度乘以一个时间常数。要让 $k$ 不超过上限，就必须让队列在版本维度上的跨度受限，这等价于限制“在途样本数”。一个可操作的伪代码思路是：</p>\n<div class=\"formula\">$$\\text{enqueue}(x, v)\\ \\text{only if}\\ v_{\\text{cur}} - v \\le k_{\\max};\\quad \\text{drop or reweight otherwise}$$</div>\n<p>这条规则把陈旧度约束从训练侧的损失函数前移到了队列入口，代价是可能丢弃已消耗算力的样本。丢弃率本身就是一个负载诊断指标：丢弃率持续偏高说明 rollout 产能过剩或训练步频过慢，两者都指向配方失配而非引擎性能问题。</p>\n<p>另一个约束是<b>权重切换的原子性窗口</b>。版本切换瞬间，rollout 引擎的在途 batch 可能跨版本，若不做原子切换，队列中样本的版本标签与实际生成权重不符，$k$ 的计算从根上失真。工程上通常让切换点对齐到 batch 边界，代价是切换期间若干 micro-batch 的空转，这部分开销随切换频率线性上升，而切换频率又由训练步频决定——于是批大小、步频、切换开销三者耦合，配方设计必须一起定。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-21\">二十一 · 并发：按陈旧度而非按利用率调</h3>\n<p>rollout 并发（同时在飞的序列数）在同步 RL 里通常按 GPU 利用率拉满，因为采样阶段独占算力、拉满即最优。异步流水线里这个直觉失效：并发越高，单位时间产出的样本越多，但队列水位上升、平均陈旧度上升，有效样本率反而可能下降。并发的最优点在“产能刚好覆盖消费速率并留出抗抖动余量”处，而不是在利用率峰值处。</p>\n<p>把这一点写成可调的反馈环：调度器观测队列水位 $W$ 与陈旧度分布的分位数（如 $k_{90}$），当 $k_{90}$ 逼近 $k_{\\max}$ 时压低 rollout 并发或提高训练步频；当 $W$ 低于安全水位时反向操作。这里的代价是<b>反馈滞后</b>：训练步频变化到队列水位响应之间有若干步的延迟，滞后过大时会出现振荡——并发调低后队列被抽空、训练侧饥饿空转，调度器再拉高并发，如此往复。抑制振荡的常用手段是给水位设死区并限制单步调节幅度，本质上是把反馈环的增益压低。</p>\n<p>并发的另一个维度是<b>长度维度的并发结构</b>。长尾样本占用 KV 显存的时间远长于短样本，若并发按序列数计而不按 KV 字节计，长尾样本会把显存吃满、迫使短样本排队，进一步拉长整体在途时间。按 KV 字节配额而非按序列数配额做并发控制，能让长尾样本的显存占用被显式计价，这是异步流水线里比连续批处理更关键的一层。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-22\">二十二 · 负载不对时的三种典型失效</h3>\n<p><b>失效一：陈旧度失控。</b>rollout 产能远超消费，队列积压，$k$ 持续增大而 $\\beta$ 未同步增大。过期样本把策略拉向旧版本方向，训练出现震荡甚至崩溃。诊断信号是 $k$ 的分位数单调上升且损失曲线出现周期性尖峰；处置是提高 $\\beta$ 或直接回退同步，代价是 wall-clock 优势丧失。</p>\n<p><b>失效二：训练侧饥饿。</b>rollout 产能不足或长度分布突然变长（策略探索期），队列被抽空，训练步等待样本，GPU 空转。这与同步 RL 的长尾阻塞在现象上相似，但成因不同：同步 RL 是单批内的长尾，这里是产能与消费的稳态失配。诊断信号是队列水位触底且 $k$ 分布集中在很小的值（因为样本一产出就被消费）。处置是提高 rollout 并发或降低训练步频，但后者会拉长迭代 wall-clock，需与 SLO 权衡。</p>\n<p><b>失效三：版本混杂。</b>权重同步通道未原子化，切换瞬间 rollout 引擎混用新旧权重，队列中样本的版本标签与实际生成权重不符。此时 $k$ 的计算失去意义，陈旧度自适应机制整体失效，且失效是静默的——损失曲线未必立刻异常。诊断需要独立校验：抽样比对样本的实际生成权重指纹与标签。这是三种失效里唯一必须靠系统层校验而非训练指标发现的。</p>\n<p>三种失效的共同点是：它们都不是引擎算力不足，而是<b>配方参数与负载形态不匹配</b>。扩容 GPU 对失效一和失效二无效甚至有害（失效一会被放大），这决定了异步 Rollout 的容量规划必须以配方为第一变量。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-23\">二十三 · 配方与硬件档位的匹配</h3>\n<p>rollout 与训练解耦部署后，两侧的硬件档位要按各自吞吐匹配，而不是按对称配置。rollout 侧是 decode 主导、KV 显存敏感、对 NVFP4/FP8 数值精度敏感（策略分布对数值扰动比分类任务更脆）；训练侧是计算与通信主导。两侧吞吐比决定了稳态队列深度，进而决定 $k$ 的典型值。若两侧档位差距过大，配方必须相应调整 $\\beta$ 与 $k_{\\max}$，否则失效一或失效二必然出现。</p>\n<p>KV cache 随权重版本切换而失效重建，这是配方里容易被忽略的一项固定开销。切换频率越高，重建开销占比越大，等效于 rollout 有效产能下降。因此<b>训练步频不能无限制提高</b>：步频提高缩短了单步 wall-clock，但增加了切换次数与重建开销，存在一个由切换开销决定的最优步频。这条曲线与陈旧度约束叠加，构成配方设计的可行域边界。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>配方取向</th><th>主要代价</th></tr></thead><tbody><tr><td>长度分布窄、收敛后</td><td>高并发、低 $k_{\\max}$、高步频</td><td>切换与 KV 重建开销占比上升</td></tr><tr><td>长度分布宽、探索期</td><td>按 KV 字节配额限并发、放宽 $k_{\\max}$、增大 $\\beta$</td><td>有效样本率下降、正则成本上升</td></tr><tr><td>产能过剩</td><td>压低并发、入口处按 $k_{\\max}$ 丢弃</td><td>已耗算力浪费、丢弃率作为诊断指标</td></tr><tr><td>产能不足</td><td>提高并发、降步频或回退同步</td><td>迭代 wall-clock 拉长</td></tr></tbody></table>\n<p>这张表的作用不是给出固定参数，而是说明配方是<b>随训练进程漂移的</b>：探索期与收敛期的负载形态不同，配方必须跟着变。把配方写死成一组常数，等价于假设长度分布与策略熵不随训练变化，这个假设在长周期 RL 里不成立。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-24\">二十四 · 一个具体例子：模板短 prompt + 漂移生成长度</h3>\n<p>设某任务 prompt 固定为短模板，生成侧在探索早期长度方差大、后期收窄。早期若按收敛期的配方（高并发、低 $k_{\\max}$）运行，长尾样本占满 KV 显存，短样本排队，队列水位虚高但有效样本率低，$k$ 分布尾部拉长，触发失效一。正确处置是把并发配额从序列数改为 KV 字节，并对超长样本单独设陈旧度上限（长样本生成耗时长，天然 $k$ 更大），同时提高 $\\beta$。后期长度收窄后，KV 压力释放，可回调并发与步频，把省下的切换开销换成更高的样本新鲜度。</p>\n<p>这个例子的工程判断落在一点上：<b>负载配方的可观测量必须是分布而非均值</b>。队列水位均值、陈旧度均值、长度均值都会掩盖双峰与长尾，而失效恰恰发生在尾部。调度器读的是 $k_{90}$、长度直方图的高分位、KV 字节占用的峰值，配方调的是这些量的约束，而不是一个标称并发数。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-25\">二十五 · 负载配方：什么样的请求形态才配得上这条流水线</h3>\n<p>异步 Rollout 流水线的收益不是免费的，它只在特定负载形态下成立：rollout 是持续不断、长度方差大的生成流，训练侧以固定步频消费，批大小由训练步频与队列水位共同决定，SLO 以训练迭代 wall-clock 与样本陈旧度分布为准。判据是长尾占比——若 rollout 时长分布的重尾使采样阶段主导迭代时间，时间重叠才有意义。此时吞吐近似为 <span class=\"formula\">$$\\text{throughput} \\approx \\frac{N_{\\text{rollout}}}{T_{\\text{rollout}}/\\text{overlap}+T_{\\text{train}}}$$</span> 分母中重叠项越小，收益越大；反之若 $T_{\\text{rollout}}$ 本身短而方差小，重叠带来的收益被权重同步与队列管理的开销吃掉，流水线反而比同步更慢。工程上先测采样阶段的墙钟占比与 P99 长度，占比不高就不要上异步。</p>\n<p>负载不对时的第一种失效是队列饥饿：训练步频快于 rollout 产出速率，队列水位持续走低，训练侧空转等待，等价于把串行等待从 rollout 端搬到了训练端。第二种是队列积压：rollout 并发过高而训练消费慢，样本在队列中排队，陈旧度 $k$ 被动增大，此时若 $\\beta$ 未同步增大，过期样本按 <span class=\"formula\">$$r_k=\\left(\\frac{\\pi_{\\theta}(x)}{\\pi_{\\theta_{v-k}}(x)}\\right)^{1/(1+\\beta k)}$$</span> 缩放后的重要性比仍不足以压制偏差，策略被拉向旧版本方向，训练震荡甚至崩溃。第三种是版本混杂：权重切换未原子化时，队列中样本的版本标签与实际生成权重不符，陈旧度估计失真，正则项打在了错误的样本上。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>适配判断</th><th>不对时的代价</th></tr></thead><tbody><tr><td>长尾显著、采样占主导</td><td>适配，重叠收益大</td><td>—</td></tr><tr><td>长度方差小、采样短</td><td>不适配</td><td>同步开销与版本管理反噬吞吐</td></tr><tr><td>rollout 产出低于训练消费</td><td>需降步频或提并发</td><td>训练侧饥饿空转，wall-clock 拉长</td></tr><tr><td>并发过高、消费慢</td><td>需限并发</td><td>队列积压、$k$ 增大、策略失真</td></tr></tbody></table>\n<p>边界由陈旧度上限决定：$k$ 的可容忍值取决于策略改进方向能承受的偏差，超过则必须回退同步或增大 $\\beta$；而 $k$ 的上限又受权重同步带宽约束——同步通道越窄，版本推进越慢，队列里样本的滞后越难压住。调度器依据队列水位与陈旧度分布动态调节 rollout 并发与训练步频，但反馈本身有滞后，水位信号跟不上步频突变时，并发与消费节奏失配，积压与饥饿会交替出现。因此负载配方的核心不是调大并发，而是让 rollout 产出速率与训练消费速率在同一量级上匹配，并把陈旧度分布作为一等监控指标，而不是只看队列长度。</p>\n<h3 id=\"alg-async-rollout-pipeline-sec-26\">二十六 · 硬件档位的匹配原则：按吞吐比而非按峰值</h3>\n<p>部署异步 Rollout 流水线的第一个决策不是选卡，而是确定 rollout 侧与训练侧的吞吐比。同步 RL 里两侧共享同一批 GPU，时间上串行，因此只需关心单卡峰值；异步流水线把两侧拆成独立资源池后，真正约束系统的是两侧的持续吞吐能否互相喂饱。设 rollout 引擎每秒产出的样本数为 $N_{\\text{rollout}}/T_{\\text{rollout}}$，训练侧每步消费 $B$ 个样本、步频为 $f_{\\text{train}}$，则稳态条件为</p>\n<div class=\"formula\">$$\\frac{N_{\\text{rollout}}}{T_{\\text{rollout}}/\\text{overlap}} \\;\\ge\\; B\\cdot f_{\\text{train}}$$</div>\n<p>这个不等式决定了档位配比：rollout 池的算力必须覆盖训练池的消费速率，且留出队列水位缓冲。工程上把 rollout 池配得略强于等式右端，让队列水位在版本切换前后有小幅回弹空间，比两侧严格相等更稳。具体例子：一个以长尾采样为主的 RL 任务，rollout 侧单步生成的长尾样本把 P99 延迟拉到均值数倍，此时若按均值配卡，训练侧必然周期性饥饿；把 rollout 池按 P99 吞吐而非均值吞吐配，训练侧步频才能稳定。代价直接体现在显存与功耗上——rollout 池多出的卡在队列高位时处于低利用率，这部分冗余是异步流水线换取 wall-clock 缩短的固定开销。</p>\n<p>档位内部还要区分预填与解码的资源比例。Rollout 的请求形态是持续流，预填占比高、解码序列长，B200/B300 的 tcgen05 与 TMEM 对大矩阵乘友好，预填阶段能吃满算力；解码阶段受 KV 带宽约束，配比失衡会让预填卡空转。判断依据是观测 rollout 引擎的预填-解码时间占比，若预填占比超过某一阈值，说明解码侧卡不足，需要把档位向解码倾斜。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-27\">二十七 · 并行拓扑：训练侧张量并行、rollout 侧数据并行</h3>\n<p>两侧的并行策略不应同构。训练侧要跑反向与优化器状态，参数分片带来的通信量与显存节省必须平衡，通常采用张量并行加流水并行；rollout 侧只做前向，权重可以整份驻留，更适合数据并行——每个 rollout 副本持有完整权重、独立处理请求流，副本间不通信。这样做的直接好处是权重同步通道的语义简单：训练侧产出新版本 $v+1$ 后，向每个 rollout 副本广播完整权重，副本原子切换，不涉及分片重组。</p>\n<p>拓扑的代价落在权重同步带宽上。若 rollout 副本数为 $R$、单份权重体积为 $W$，一次版本切换的广播量为 $R\\cdot W$，经 NVLink 5 与 NCCL 走树形或环形广播。切换频率由训练步频决定，因此同步带宽需求为 $R\\cdot W\\cdot f_{\\text{train}}$。当 $R$ 增大到广播时间接近训练步间隔时，同步通道成为瓶颈，此时要么降低切换频率（允许更大陈旧度 $k$），要么减少副本数、提高单副本并发。GB200/GB300 NVL72 机柜内 NVLink 域大，广播延迟低，适合高 $R$；跨机柜部署则要重新核算这条带宽账。</p>\n<p>具体例子：rollout 侧 8 个数据并行副本、每份权重经 FP8 量化后体积可控，一次广播在机柜内 NVLink 域内完成的时间远小于一个训练步，切换对训练步频的扰动可忽略；若把副本数翻倍而不调整步频，广播时间线性增长，最终与训练步同量级，版本切换开始拖慢训练节奏。这就是并行拓扑与调度参数必须联合定的原因。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-28\">二十八 · 量化方案：rollout 用 NVFP4/FP8，训练侧保持高精度</h3>\n<p>两侧精度策略不对称是异步流水线的关键设计。训练侧的反向传播与优化器更新对数值敏感，保持 BF16/FP16；rollout 侧只做前向采样，可以激进量化以提升吞吐、压缩权重体积、加快同步。NVFP4 在 Blackwell 上有原生支持，权重与激活都压到 4 位，配合分块缩放因子维持动态范围；FP8 则是更保守的选择，精度损失小、工具链成熟。选择依据是策略分布对量化误差的容忍度：采样温度高、动作空间离散的任务，量化误差被 softmax 平滑，NVFP4 可用；温度低、策略尖锐的任务，FP8 更稳。</p>\n<p>量化对系统的影响有三条。其一，权重体积缩小直接降低同步广播量，$W$ 减小使 $R\\cdot W\\cdot f_{\\text{train}}$ 下降，缓解并行拓扑一节里的带宽瓶颈。其二，rollout 前向的算力吞吐提升，tcgen05 在低精度下矩阵乘吞吐更高，rollout 池可用更少卡达到同等样本产出。其三，量化引入的数值偏差会与陈旧度偏差叠加：过期样本本身已带 off-policy 偏差，再叠加量化噪声，重要性比的方差被放大。因此量化方案要与陈旧度惩罚强度 $\\beta$ 联动标定——量化越激进，$\\beta$ 的基线越要高一些，用更强的信任域约束抵消数值噪声。</p>\n<p>具体机制上，rollout 侧量化在权重同步通道的接收端完成：训练侧广播高精度权重，rollout 副本在原子切换时同步做量化转换，转换后的权重与版本号绑定存储。这样训练侧不必维护量化副本，切换语义清晰。代价是每次切换多一次转换开销，转换时间与权重体积成正比，需计入切换窗口。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-29\">二十九 · KV 策略：随版本失效重建与跨版本复用边界</h3>\n<p>异步流水线里 KV cache 的命运与权重版本强绑定。权重从 $v$ 切到 $v+1$ 后，旧版本生成的 KV 对应的注意力分布已不再匹配新策略，继续复用会引入隐性偏差。部署配方的基本规则是：KV cache 随权重版本切换而失效重建，每个 rollout 副本在原子切换时清空本地 KV 池，新请求从零预填。这条规则简单、正确，代价是切换瞬间的预填尖峰——所有副本同时清空，紧接着的请求全部走预填，rollout 吞吐在切换窗口内短暂塌陷。</p>\n<p>缓解手段是错峰切换与部分复用。错峰切换让各副本在不同时刻完成版本切换，预填尖峰被摊平，代价是切换窗口内队列中样本版本混杂，需要版本标签严格校验。部分复用则针对前缀 KV：若某请求的前缀在版本切换前已预填、且该前缀对应的上下文在新旧策略下语义稳定（例如系统提示、固定工具描述），可保留这部分 KV，只重建后续部分。复用边界的判断依据是前缀 token 是否参与策略分布的关键计算，工程上以固定前缀为界最安全。</p>\n<p>KV 策略的显存代价要单独核算：rollout 副本的 KV 池按并发请求数与序列长度定容，切换重建意味着池内存在瞬时双份占用（旧 KV 待释放、新 KV 待补全充），显存峰值出现在切换窗口。若池容量按稳态配，切换窗口会触发驱逐，反而拖慢预填。配方上给 KV 池留出切换余量，或采用分页 KV 管理让新旧页在切换时快速回收，是两种可行路径。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-30\">三十 · 调度参数：队列水位、陈旧度上限与并发联动</h3>\n<p>调度参数是部署配方里唯一需要在线整定的部分。核心三个量：队列水位 $Q$、陈旧度上限 $k_{\\max}$、rollout 并发度 $C$。三者通过反馈环耦合——队列水位与陈旧度分布反馈给调度器，动态调节 rollout 并发与训练步频。稳态下，$Q$ 维持在能覆盖一次版本切换窗口的深度：太浅则训练侧饥饿，太深则样本平均陈旧度上升。$k_{\\max}$ 由策略改进方向的可容忍偏差决定，超过则回退同步或增大 $\\beta$；$C$ 跟随 $Q$ 与 $k$ 的实测分布调整，队列积压时降并发、训练饥饿时升并发。</p>\n<p>具体机制可用一个简单的比例控制描述：调度器每步读取队列水位偏差 $\\Delta Q = Q_{\\text{target}} - Q_{\\text{obs}}$ 与陈旧度分布的分位数，按</p>\n<div class=\"formula\">$$C_{t+1} = C_t + \\alpha\\,\\Delta Q - \\gamma\\,\\mathbb{1}[k_{p99} &gt; k_{\\max}]$$</div>\n<p>调整并发，其中 $\\alpha$ 为水位增益、$\\gamma$ 为陈旧度惩罚步长。这个控制律的工程意义是把两个失败模式分开处理：队列积压靠降并发解决，陈旧度超限靠降并发加提 $\\beta$ 解决。失败模式里明确列出的一条是队列水位反馈滞后于训练步频变化，rollout 并发与训练消费节奏失配，出现队列积压或训练侧饥饿空转——控制环的采样周期必须短于训练步频变化的时间尺度，否则增益再调也追不上。</p>\n<p>调度参数的代价体现在训练稳定性上。$k_{\\max}$ 设得松，wall-clock 缩短明显但策略震荡风险上升；设得紧，异步收益被压缩回同步水平。配方上以陈旧度分布的分位数而非均值做判据，因为长尾样本才是把策略拉向旧版本方向的主力。具体例子：某任务实测 $k$ 的 P99 长期贴近上限而均值远低于上限，说明少数极旧样本在拖后腿，此时应降并发并提高 $\\beta$，而不是整体收紧 $k_{\\max}$ 牺牲吞吐。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-31\">三十一 · 可复现的配置思路：从吞吐账到参数表的落地顺序</h3>\n<p>把上述决策串成可复现的流程，顺序是：先算吞吐账，再定拓扑，再定量化，再定 KV，最后整定调度。吞吐账用第一节的不等式，输入是训练侧步频与批大小、rollout 侧实测 P99 吞吐；账算不平则先调档位配比，不要急着调调度参数。拓扑按同步带宽需求 $R\\cdot W\\cdot f_{\\text{train}}$ 定副本数，量化方案按策略尖锐度在 NVFP4 与 FP8 间选，并据此修正 $W$ 重算带宽。KV 策略默认随版本失效重建，按切换窗口的预填尖峰决定是否引入错峰或前缀复用。调度参数最后整定，用比例控制起步，以陈旧度 P99 与队列水位两个观测量分别对应两类失败模式。</p>\n<p>配置表可按以下结构组织，每一行都对应一个可观测的判据：</p>\n<table class=\"mini\"><thead><tr><th>配置项</th><th>取值依据</th><th>观测判据</th><th>失配代价</th></tr></thead><tbody><tr><td>rollout 池规模</td><td>P99 吞吐覆盖训练消费速率</td><td>队列水位稳态偏差</td><td>训练侧饥饿空转</td></tr><tr><td>并行拓扑（副本数 $R$）</td><td>广播量 $R\\cdot W\\cdot f_{\\text{train}}$ 低于步间隔</td><td>版本切换耗时占比</td><td>同步通道成瓶颈</td></tr><tr><td>量化方案</td><td>策略尖锐度与量化噪声容忍</td><td>重要性比方差</td><td>与陈旧度偏差叠加</td></tr><tr><td>KV 策略</td><td>切换窗口预填尖峰与显存余量</td><td>切换窗口吞吐塌陷深度</td><td>驱逐触发、预填变慢</td></tr><tr><td>并发度 $C$ 与 $k_{\\max}$</td><td>陈旧度 P99 与水位偏差</td><td>策略震荡、队列积压</td><td>wall-clock 收益回退</td></tr></tbody></table>\n<p>这套配置思路的可复现性来自判据的可观测性：每一行都有对应的在线指标，配置调整后指标的变化方向可预期。真正的工程判断落在优先级上——当吞吐账算不平且调度参数已整定到边界时，回退同步或增大 $\\beta$ 是比继续加卡更稳的选择，因为陈旧度上限由策略改进方向的可容忍偏差决定，不是靠堆资源能突破的。版本切换的原子性是整条流水线的硬约束：切换未原子化导致队列样本版本标签与实际生成权重不符，这个失败模式无法靠任何调度参数补救，只能在权重同步通道的实现里保证。</p>\n<h3 id=\"alg-async-rollout-pipeline-sec-32\">三十二 · 显存：版本切换把 KV 变成一次性资产</h3>\n<p>异步流水线的显存账不能按稳态算，要按版本切换的瞬态算。rollout 引擎持有两样东西：权重副本与 KV cache。权重副本随版本 $v$ 增长而膨胀——训练侧推送 $v+1$ 时，rollout 侧必须同时容纳旧权重（正在跑的请求还在用）与新权重（已切换的请求要用），双份权重驻留是异步相对同步多出来的固定开销。KV cache 的问题更尖锐：部署配方里明确写了“KV cache 随权重版本切换而失效重建”，这意味着每次版本切换，rollout 引擎里所有在途请求的 KV 前缀都作废。分页 KV 批量 Rollout 那套块管理在这里帮不上忙——块还在，但块里的 K/V 是用旧权重算出来的，喂给新权重的前向就是数值污染。工程上的做法是按版本给 KV 池打标签，切换时把旧版本块标记为不可复用、等待自然驱逐，新请求从空池起算。代价是切换瞬间有效 KV 容量腰斩，长上下文请求的 prefill 成本被重复支付。</p>\n<p>把这个代价量化：设 rollout 引擎 KV 池容量为 $C$，版本切换周期为 $T_v$，切换后到池重新填满的时间约为 $T_v/2$（均匀到达假设）。则平均有效 KV 容量为</p>\n<div class=\"formula\">$$C_{\\text{eff}} \\approx C\\left(1 - \\frac{1}{2}\\cdot\\frac{T_{\\text{refill}}}{T_v}\\right)$$</div>\n<p>其中 $T_{\\text{refill}}$ 是池从空到满所需时间，由请求到达率与平均序列长度决定。$T_{\\text{refill}}$ 接近 $T_v$ 时，$C_{\\text{eff}}$ 掉到 $0.5C$ 量级，rollout 并发被迫下调，队列水位上升，训练侧开始饥饿。具体例子：一个 70B 级模型在 NVL72 单节点上跑 rollout，权重副本按 FP8 约 70GB，双份驻留即 140GB；KV 池若按每 token 每层 2 字节（FP8 KV）估算，长上下文请求占主导时池子被序列长度吃掉的速度远快于被并发数吃掉。规模上去以后，显存先崩的点不在权重，而在“切换瞬态 + 长序列 KV”的乘积。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-33\">三十三 · 带宽：权重同步是异步流水线的隐性税</h3>\n<p>权重同步通道是这条流水线里唯一一个“训练侧主动、rollout 侧被动”的环节，它的带宽需求随规模线性上升而收益不随规模上升。设模型参数量 $P$、权重精度字节数 $b$、同步周期 $T_v$，则同步通道所需带宽为</p>\n<div class=\"formula\">$$B_{\\text{sync}} \\approx \\frac{P\\cdot b}{T_v}$$</div>\n<p>以 FP8 权重、$P=70\\text{B}$、$T_v$ 取训练若干步的时间计，单次推送就是数十 GB 量级；若 rollout 引擎分布在多个节点，这份权重还要经 NVLink 5 与节点间链路扇出，扇出倍数等于 rollout 副本数。NVLink 5 的机内带宽足以承载单次推送，但扇出到 NVL72 全机架时，同步窗口会与 rollout 的 prefill 流量、KV 传输流量争抢同一批链路。工程判断是：同步不能“全量推、随时推”，要按层或按张量分片推、与 rollout 的 decode 低峰对齐，并在 rollout 侧做双缓冲——新权重写进影子缓冲、原子切换指针，避免切换瞬间的读写冲突。这正是失败模式里“版本切换未原子化导致样本版本标签与实际权重不符”的系统根源：不是逻辑错，是带宽窗口内没做双缓冲。</p>\n<p>带宽的第二个消耗点是样本队列本身。异步允许滞后 $k$ 个版本，队列里驻留的样本数正比于 $k$ 与训练消费速率之积。样本是 token 序列加 logprob、版本号等元数据，单条不大，但队列水位高时，队列的写入与读取会与 KV 传输共享同一套 NIXL 通道。队列管理不是零成本抽象，它是一条真实的带宽流。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-34\">三十四 · 通信：尾延迟在异步下换了形态但没消失</h3>\n<p>同步 RL 的尾延迟表现为“训练步等最慢的那条 rollout 样本”。异步流水线用时间重叠把这个等待藏起来了，但尾延迟没有消失，它转移到了两个地方：队列的版本分布尾部，与权重同步的完成时刻。前者是数据面的尾，后者是控制面的尾。</p>\n<p>数据面：队列里样本的陈旧度 $k$ 是一个分布，不是常数。调度器按水位调并发，但水位反馈本身有滞后——失败模式第三条讲的就是“队列水位反馈滞后于训练步频变化，出现队列积压或训练侧饥饿空转”。当训练步频突然加快（比如换了更小的批），消费速率上升，队列被抽干，训练侧取到的样本 $k$ 偏小甚至队列空；反之训练变慢，队列积压，$k$ 的尾部拉长，过期样本开始拉扯策略。尾延迟在这里的度量不是毫秒，而是 $k$ 的 P99。工程上要把 $k$ 的分布而不是均值喂给调度器，并对 $k$ 超过阈值的样本直接丢弃而非降权使用——丢弃是显式的尾延迟截断。</p>\n<p>控制面：权重同步的完成时刻决定了版本切换的原子性窗口。若同步分片推送，最后一片到达前 rollout 侧不能切换，这段窗口内 rollout 仍在用旧权重生成，队列里新旧版本混杂。窗口长度由最慢分片的传输时间决定，是典型的尾延迟主导量。规模上去以后，扇出副本越多，最慢分片的概率越大，窗口越长，混杂越严重。这是异步流水线在规模上第二个先崩的点：不是平均带宽不够，是同步窗口的尾部随副本数增长。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-35\">三十五 · 功耗与吞吐：overlap 不等于免费</h3>\n<p>吞吐公式在公式与推导部分已经给出，这里只算它的分母里被忽略的一项：overlap 不是把两份工作塞进同一段时间就完事，它要求训练侧与 rollout 侧同时满负荷，功耗曲线因此从同步模式的“脉冲式”变成“平台式”。同步 RL 的功耗特征是 rollout 阶段高、训练阶段高、中间等待阶段低，平均功耗被空转拉低；异步流水线把空转填满，平均功耗上升，机架的供电与散热余量被吃掉。NVL72 这种高密度机架里，功耗平台化意味着不能靠“峰值不超过”来设计供电，要按持续满载设计。工程判断：异步流水线的吞吐收益有一部分会被功耗墙抵消，尤其在 rollout 与训练共用同一批 GPU 的部署里——分离式部署（rollout 引擎与训练侧解耦）反而在功耗上更可控，因为两侧可以各自按自己的负载曲线调频。</p>\n<p>吞吐的另一个隐性代价是权重版本切换期间的算力空窗。切换瞬间 rollout 引擎的 KV 池失效、新请求 prefill 成本上升、旧请求被丢弃或等待，这段窗口的 rollout 吞吐低于稳态。设切换窗口占版本周期的比例为 $f$，则有效 rollout 吞吐为稳态吞吐的 $1-f$ 倍。$f$ 随 KV 池大小与请求长度上升，规模上去以后 $f$ 不可忽略。这与显存部分的 $C_{\\text{eff}}$ 是同一个现象的两个视角：显存账算容量，吞吐账算时间。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-36\">三十六 · 规模上去以后哪里先崩：三个阈值</h3>\n<p>把前四节的代价按规模排序，可以得到一条崩溃顺序，而不是一个笼统的“规模受限”。</p>\n<table class=\"mini\"><thead><tr><th>阈值</th><th>触发条件</th><th>先崩的表现</th><th>缓解手段</th></tr></thead><tbody><tr><td>显存阈值</td><td>双份权重 + 切换瞬态 KV 失效使 $C_{\\text{eff}}$ 跌破并发需求</td><td>rollout 并发被迫下调，队列水位上升，训练侧饥饿</td><td>按层分片同步缩短切换窗口；旧版本 KV 块延迟驱逐而非立即作废</td></tr><tr><td>带宽阈值</td><td>权重扇出副本数 × 单次推送量超过同步窗口可用带宽</td><td>同步窗口尾部拉长，版本混杂，$k$ 分布尾部变厚</td><td>双缓冲原子切换；同步与 decode 低峰对齐；减少 rollout 副本数换取更大单副本</td></tr><tr><td>偏差阈值</td><td>$k$ 的 P99 超过 $\\beta$ 能约束的范围</td><td>过期样本把策略拉向旧版本方向，训练震荡</td><td>丢弃超阈值样本；增大 $\\beta$；回退同步</td></tr></tbody></table>\n<p>三个阈值的先后顺序取决于负载配方：长序列为主的 rollout 先撞显存阈值，因为 KV 失效的代价被序列长度放大；多副本扇出的部署先撞带宽阈值，因为同步窗口尾部随副本数增长；训练步频快、消费速率高的配方先撞偏差阈值，因为队列被抽干后 $k$ 的分布反而更不稳定。具体例子：一个以长文档生成为主的 RL 任务，rollout 平均序列长度在数千 token 量级，KV 池在版本切换后重新填满的时间接近版本周期，显存阈值最先触发；此时即便带宽充裕，rollout 并发也上不去，吞吐被显存锁死。反过来，一个短序列、高并发的任务，KV 池周转快，显存不是瓶颈，但权重扇出到多副本时同步窗口成为限制。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-37\">三十七 · 工程判断：把尾延迟当一等指标</h3>\n<p>异步流水线的调度器如果只看队列水位均值，会在规模上去以后失稳——均值掩盖了 $k$ 的尾部，而尾部才是偏差与崩溃的来源。可操作的机制是把 $k$ 的分布、同步窗口的完成时刻、KV 池的有效容量三个量一起喂给调度器，用它们共同决定 rollout 并发与训练步频。伪代码思路：</p>\n<ul>\n<li>每步读取队列样本的版本号，计算 $k$ 的直方图而非均值；</li>\n<li>若 $k$ 的 P99 超过阈值 $k_{\\max}$，触发丢弃策略并临时增大 $\\beta$；</li>\n<li>若同步窗口未闭合（最慢分片未到），rollout 侧拒绝切换、继续用旧版本生成，并把该窗口时长计入下一周期的并发下调量；</li>\n<li>若 $C_{\\text{eff}}$ 低于并发需求，优先缩短版本周期而非增大 $\\beta$——显存问题不能用正则解决。</li>\n</ul>\n<p>最后一条是本部分最硬的判断：偏差阈值可以用 $\\beta$ 与丢弃来调，显存与带宽阈值不能。规模上去以后，先崩的往往是显存或带宽这类物理量，而调度器若只会调 $\\beta$，就会在物理量已经越界时继续加正则，表现为训练不崩但吞吐持续下滑——这是异步流水线最隐蔽的失败形态，比训练震荡更难定位。把 $C_{\\text{eff}}$ 与同步窗口时长做成调度器的一等输入，而不是事后诊断指标，是这条流水线在 NVL72 规模上还能保持吞吐的前提。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-38\">三十八 · 规模放大后的四道墙：带宽、显存、尾延迟与功耗</h3>\n<p>异步流水线把 wall-clock 从「采样串行」里解放出来，但它并不消除代价，只是把代价从时间轴搬到了系统资源轴上。规模上去以后，第一个先崩的通常不是算力，而是<strong>权重同步带宽</strong>。rollout 引擎与训练侧解耦部署，每个训练步产出新权重 $v+1$ 都要经同步通道推送到全部 rollout 副本并原子切换；当 rollout 副本数随并发线性增长，单步同步的数据量随副本数线性放大，同步时间开始与训练步时间同量级，重叠收益被吃掉。判断边界的不等式很直接：设单副本权重体积 $W$、副本数 $M$、通道有效带宽 $B$，则同步开销 $T_{\\text{sync}} \\approx MW/B$，只有当 $T_{\\text{sync}} \\ll T_{\\text{train}}$ 时异步才划算。NVL72 域内 NVLink 5 能把 $B$ 抬得很高，跨域则退化为 NIC 带宽，此时 $M$ 的上限被硬性压住——这正是「规模受权重同步带宽约束」的工程含义。</p>\n<p>第二道墙是<strong>KV cache 与显存</strong>。版本切换瞬间 KV cache 随权重版本失效重建，意味着 rollout 引擎的显存里同时存在「正在生成的旧版本请求」与「等待新版本的空闲块」，切换越频繁，重建浪费的显存带宽越多。队列水位高时，积压样本本身也占内存；水位反馈滞后于训练步频变化，就会出现队列积压或训练侧饥饿空转两种反向失效。吞吐的粗算可写成 throughput ≈ $N_{\\text{rollout}}/(T_{\\text{rollout}}/\\text{overlap}+T_{\\text{train}})$，其中 $N_{\\text{rollout}}$ 受队列容量与陈旧度上限双重截断——陈旧度 $k$ 的上限由策略改进方向的可容忍偏差决定，队列不能无限深，于是 $N_{\\text{rollout}}$ 有天花板，overlap 再高也换不来线性吞吐。</p>\n<p>第三道墙是<strong>尾延迟与陈旧度分布的耦合</strong>。同步 RL 的痛点是长尾样本阻塞训练步；异步把长尾留在 rollout 侧，但长尾样本恰恰是陈旧度最大的那批——它们生成得最慢，进入队列时当前版本已推进若干步，$k$ 偏大。若 $\\beta$ 未随 $k$ 同步增大，过期样本把策略拉向旧版本方向，训练震荡甚至崩溃。因此调度器真正要盯的不是平均队列水位，而是<strong>陈旧度分布的右尾</strong>：右尾变厚就应降 rollout 并发或提训练步频，把 $k$ 压回信任域内；反之队列见底则说明训练侧饥饿，需反向调节。这是一条以分布形状为输入的反馈环，而非单点水位阈值。</p>\n<p>第四道墙是<strong>功耗与版本混杂</strong>。rollout 与训练同时满载，整机功耗逼近封装上限，持续高负载下的时钟回落会同时拉低两侧吞吐，重叠收益被热约束折损。更隐蔽的失效在版本切换：若同步通道未原子化，rollout 引擎混用新旧权重，队列中样本版本标签与实际生成权重不符，$k$ 的记录失真，信任域缩放建立在错误前提上。工程判断是：把原子切换做成硬约束（切换期间暂停取样或双缓冲隔离），并把 $k$ 的实测值与标签做周期性一致性校验；规模上限应由 $MW/B$ 与陈旧度右尾共同决定，任一越界即回退同步或增大 $\\beta$。</p>\n<h3 id=\"alg-async-rollout-pipeline-sec-39\">三十九 · 陈旧度漂移：从统计量到可观测信号</h3>\n<p>异步流水线最危险的失败不是崩溃，而是“缓慢地朝错误方向收敛”。当 rollout 引擎的生成速度与训练消费速度失配时，队列中样本的生成版本与训练侧当前版本之间的差距 $k$ 会持续漂移；若 $\\beta$ 固定不变，过期样本对策略的拉扯权重被低估，重要性比 $r_k$ 的方差随之放大。诊断的第一步是把 $k$ 从隐变量变成一等指标：在样本入队时打上版本号，训练侧取批时计算 $k$ 的分布，而不是只看均值。</p>\n<p>具体机制上，训练侧每步取批后记录该批的 $k$ 直方图，并把 $P(k&gt;k_{\\max})$ 作为硬性告警阈值；同时统计经陈旧度缩放后 $r_k$ 的有效样本量（ESS），当 ESS 相对名义批大小显著下降时，说明少数过期样本在主导梯度。公式上，$r_k=\\left(\\pi_\\theta(x)/\\pi_{\\theta_{v-k}}(x)\\right)^{1/(1+\\beta k)}$ 的指数项随 $k$ 增大而收缩，但收缩速度由 $\\beta$ 决定；若 $k$ 的尾部增长快于 $\\beta$ 的调节能力，缩放不足以压制偏差。</p>\n<div class=\"formula\">$$\\mathrm{ESS}=\\frac{\\left(\\sum_i r_{k,i}\\right)^2}{\\sum_i r_{k,i}^2},\\quad \\text{告警条件：}\\ \\mathrm{ESS}/N_{\\text{batch}}&lt;\\epsilon_{\\text{ESS}}$$</div>\n<p>系统代价体现在两个方向：诊断本身要占用训练侧的少量算力做归约，但相比一次因震荡导致的回滚重跑，代价可以忽略；真正的代价是滞后——$k$ 的漂移往往在若干训练步之后才反映到 loss 曲线上，因此监控必须前置到队列层而非 loss 层。一个具体例子：rollout 引擎因长尾样本堆积导致消费端饥饿，训练侧被迫从更深位置取样本，$k$ 的 95 分位从个位数跳到两位数，此时若只看平均 loss 仍平稳，但 ESS 已跌破阈值，这就是需要触发 $\\beta$ 上调或并发调节的信号。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-40\">四十 · 精度异常：NVFP4 与异步叠加的隐蔽退化</h3>\n<p>异步带来的 off-policy 偏差与低精度量化的数值误差会相互放大，且这种退化在 loss 上表现为“缓慢抬升而非爆炸”，极易被误判为陈旧度问题。NVFP4 的块级缩放使权重与激活的动态范围被压缩，当策略被过期样本拉向旧版本方向时，梯度方向本身已经偏离，量化误差再叠加一层，最终表现为重要性比分布的尾部变厚、KL 惩罚项异常抬升。</p>\n<p>诊断机制应当把精度异常与陈旧度异常解耦：在训练侧对每批样本同时记录 $r_k$ 的分位数与 KL 项的分解值，若 $r_k$ 尾部正常而 KL 项单调抬升，则优先怀疑量化路径而非 $k$；反之若 $r_k$ 尾部与 $k$ 同步恶化，则是陈旧度主导。工程上可做一次“精度对照回放”：取同一批带版本号的样本，用高精度路径重算一次重要性比，比较两条路径的 $r_k$ 偏差，偏差超过阈值即判定为量化退化。</p>\n<ul>\n<li>监控点：$r_k$ 的 99 分位、KL 项的分版本均值、量化路径与高精度路径的 $r_k$ 相对偏差。</li>\n<li>代价：对照回放需要额外一次前向，占用训练侧算力与显存；但相比整轮回滚，单批回放的代价可控。</li>\n<li>具体例子：某批样本 $k$ 分布正常，但 $r_k$ 的 99 分位显著高于历史基线，且高精度回放显示偏差集中在少数 token 上，定位为 NVFP4 激活缩放因子在版本切换后未及时刷新。</li>\n</ul>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-41\">四十一 · OOM 与批抖动：队列水位与显存的双向耦合</h3>\n<p>异步流水线的 OOM 很少是单点爆发，而是队列水位、批大小与 KV cache 三者耦合的结果。rollout 引擎持续生成、训练侧按节奏消费，当消费变慢时队列积压，样本本身占用主机或显存侧缓冲；同时 rollout 侧为维持吞吐会抬高并发，KV cache 随并发线性增长。版本切换时 KV cache 失效重建，瞬时显存需求出现尖峰，这是最典型的 OOM 触发点。</p>\n<p>批抖动则是 OOM 的前兆：训练侧为躲避显存压力而动态缩小批大小，批变小导致梯度噪声上升，进而触发更多正则与更慢的收敛，反过来拉长消费周期、加剧队列积压。诊断要把批大小的时间序列与队列水位、KV cache 占用放在同一时间轴上对齐，找出“批大小下调—水位上升—KV 重建”的因果链，而不是孤立看单指标。</p>\n<table class=\"mini\"><thead><tr><th>信号</th><th>典型形态</th><th>判读</th></tr></thead><tbody><tr><td>队列水位</td><td>单调爬升后骤降</td><td>消费侧节奏突变或版本切换重建</td></tr><tr><td>批大小</td><td>锯齿状下调</td><td>显存压力驱动的被动缩批</td></tr><tr><td>KV 占用</td><td>版本切换点尖峰</td><td>缓存失效重建的瞬时需求</td></tr></tbody></table>\n<p>系统代价上，OOM 一次即意味着整步训练作废并重跑，wall-clock 损失以分钟计；批抖动虽不致命，但持续缩批会把有效批大小压到信任域估计失真的区间。工程判断是给队列水位设硬上限并在接近上限时优先降 rollout 并发而非缩训练批，因为缩批会直接损害策略改进质量。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-42\">四十二 · 路由不均与尾延迟尖刺：调度器的反馈滞后</h3>\n<p>当 rollout 引擎以多实例部署、样本按路由分发时，路由不均表现为部分实例队列深、部分实例空闲，整体吞吐被最慢实例拖住。异步流水线里这种不均在尾延迟上被放大：训练侧按固定节奏消费，若某批样本恰好来自深队列实例，其 $k$ 显著偏大，形成周期性的尾延迟尖刺，表现为训练步时间的规律性抖动。</p>\n<p>诊断机制是把尾延迟按来源拆解：记录每批样本的来源实例、入队时间与取批时间，计算“等待时间”与“生成时间”的分解；若等待时间占比高且集中在少数实例，则是路由不均而非生成慢。调度侧的反馈回路存在固有滞后——队列水位反馈到并发调节需要若干步才能生效，这期间尖刺会重复出现，因此监控需要区分“瞬时尖刺”与“持续性偏移”。</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx \\max_i\\left(T_{\\text{gen},i}+T_{\\text{wait},i}\\right)+T_{\\text{train}},\\quad \\text{尖刺判据：}\\ T_{\\text{wait},i}\\gg \\overline{T_{\\text{wait}}}$$</div>\n<p>具体例子：四个 rollout 实例中一个因长尾样本积压，其队列深度是其余实例的数倍，训练侧每取到该实例样本时步时间抬升，形成每若干步一次的尖刺；把该实例的并发上限下调并做样本再平衡后，尖刺消失而整体吞吐未降。代价是再平衡本身要迁移队列中的样本，迁移期间该实例的有效吞吐下降，需在低水位窗口执行。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-43\">四十三 · 回滚策略：版本原子性与检查点粒度</h3>\n<p>回滚的第一原则是版本原子性。权重同步通道若在切换瞬间未原子化，rollout 引擎会混用新旧权重，队列中样本的版本标签与实际生成权重不符——这比陈旧度本身更危险，因为它让 $k$ 的计算失去意义。诊断这类问题的信号是：同一版本标签下的样本，其重要性比分布出现双峰。工程上要求权重推送走“准备—切换—确认”三段式，切换点之后入队的样本才带新版本号，切换点之前的样本要么丢弃要么标记为跨版本。</p>\n<p>回滚粒度取决于检查点策略：若只保存训练侧权重，回滚意味着丢弃队列中所有在途样本并重建 KV cache，代价是一次完整的冷启动；若同时保存队列快照与版本标签，回滚可以只回退训练侧权重而保留队列，让新权重消费旧样本并靠 $\\beta$ 上调压制偏差。后者代价更低但要求队列快照与权重检查点时间对齐。</p>\n<ul>\n<li>触发条件：ESS 跌破阈值持续若干步、KL 项单调抬升且精度对照排除量化因素、$P(k&gt;k_{\\max})$ 超限。</li>\n<li>回滚动作序列：冻结消费、上调 $\\beta$、原子切换权重、按需丢弃跨版本样本、重建 KV cache、恢复消费。</li>\n<li>代价：冷启动回滚损失整段在途样本与一次 KV 重建；温和回滚仅损失若干步的训练进度，但需承担旧样本的残余偏差。</li>\n</ul>\n<p>最后落在工程判断上：异步流水线的稳定性不取决于单点监控的灵敏度，而取决于“陈旧度—精度—显存—路由”四条信号是否在同一时间轴上对齐判读；把 $k$ 分布、ESS、KV 占用与来源实例等待时间做成同屏时序，才能在下一次尾延迟尖刺出现时区分它是路由不均、量化退化还是版本切换的瞬时混杂，而不是在 loss 抬升后才被动回滚。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-44\">四十四 · 陈旧度失控、版本混杂与队列失配：异步流水线的三类硬失效与观测回滚</h3>\n<p>异步流水线的边界不在“能不能重叠”，而在“重叠多久仍可控”。第一类硬失效是陈旧度漂移：样本生成版本与当前版本差距 $k$ 超过可容忍上限，而 $\\beta$ 未随 $k$ 同步增大，过期样本把策略拉向旧版本方向。此时信任域缩放失效——$r_k$ 的指数 $1/(1+\\beta k)$ 本应压制旧样本权重，但 $\\beta$ 固定时，$k$ 增大只让分母缓慢增长，重要性比仍接近 1，KL 惩罚 $\\beta k\\,\\mathrm{KL}$ 的线性增长不足以抵消策略梯度被旧方向牵引。诊断信号不是单点 loss，而是**陈旧度分布的分位数漂移**：队列中 $k$ 的 p99 持续抬升、同时策略熵骤降或梯度范数震荡，即说明样本在“拖后腿”。工程代价直接体现在训练稳定性上：一次陈旧度失控往往需要回退若干步权重并重建队列，wall-clock 损失以分钟计，远大于单步重叠收益。判断规则是设硬阈值 $k_{\\max}$，一旦 p99 越过即触发回退同步或临时增大 $\\beta$，而不是等 loss 发散后再救。</p>\n<p>第二类失效是版本切换的非原子性。权重经同步通道从训练侧推送到 rollout 引擎，若切换瞬间未原子化，rollout 引擎会混用新旧权重，队列中样本的版本标签与实际生成权重不符。这种“标签说谎”比陈旧度更危险：训练侧按标签计算 $k$，实际偏差被低估，信任域约束形同虚设。诊断靠**版本一致性校验**——在样本入队时记录生成侧权重哈希，训练侧消费时比对标签哈希，不一致样本直接丢弃并计入混杂率。代价是吞吐：丢弃意味着有效样本率下降，队列水位被动抬升，调度器若仍按名义并发推 rollout，会进一步放大积压。回滚手段是把权重同步做成双缓冲加屏障：新版本写入影子缓冲，rollout 引擎在批边界一次性切换指针，切换窗口内的在途请求标记为“跨版本”并降权消费，而非直接混入。</p>\n<p>第三类失效是队列水位反馈滞后于训练步频变化。调度器依据水位与陈旧度分布动态调节 rollout 并发与训练步频，但反馈回路本身有延迟：训练侧突然加速消费时，水位骤降，rollout 并发来不及抬升，训练侧饥饿空转；反之训练步频放慢，队列积压，样本 $k$ 被动增大，退化成第一类失效。可用小表刻画两种失配的观测口径：</p>\n<table class=\"mini\"><thead><tr><th>失配方向</th><th>观测信号</th><th>系统代价</th><th>回滚动作</th></tr></thead><tbody><tr><td>训练饥饿</td><td>队列水位低于下限、取批等待时间上升</td><td>训练 GPU 空转，重叠收益归零</td><td>临时提升 rollout 并发或降步频</td></tr><tr><td>队列积压</td><td>水位高于上限、$k$ 的 p99 抬升</td><td>陈旧度上升，需增大 $\\beta$ 或丢弃</td><td>加速消费或截断旧版本样本</td></tr></tbody></table>\n<p>监控口径应统一到“迭代 wall-clock + 陈旧度分布 + 混杂率”三元组，而不是单看吞吐。吞吐近似 $\\frac{N_{\\text{rollout}}}{T_{\\text{rollout}}/\\text{overlap}+T_{\\text{train}}}$ 只在重叠有效时成立；一旦饥饿或积压，分母中的重叠项退化，名义吞吐虚高。回滚的工程判断是：把 $k_{\\max}$、混杂率上限、水位上下限设为三条硬线，任一越线即降级为同步或半同步模式，优先保策略改进方向不失真，再谈重叠收益——异步的收益永远让位于可回滚的稳定性。</p>\n<h3 id=\"alg-async-rollout-pipeline-sec-45\">四十五 · 同族谱系：把十几种 Rollout 算法放到同一张坐标系</h3>\n<p>要在这十几种 Rollout 算法之间做选择，先要承认它们并不是同一层的替代品。分页 KV 批量 Rollout、分块预填背驮解码、预填解码分离 Rollout、KV 中心分离式池化，解决的是<b>显存与预填/解码的资源形态</b>；特征级投机采样、NVFP4 量化稳定化、批不变采样，解决的是<b>数值与采样语义</b>；在线剪枝、前缀 KV 共享、异构 Agent 协同，解决的是<b>样本筛选与复用</b>；而异步 Rollout 流水线处理的是<b>时间维度</b>——rollout 与训练谁等谁。因此决策的第一刀不是\"哪个更快\"，而是\"瓶颈落在哪一维\"。若瓶颈是 KV 容量与预填算力，异步流水线只会把长尾从训练侧搬到队列里，wall-clock 缩短有限；若瓶颈是训练步被采样长尾拖住、GPU 在等待中空转，则只有异步这一类能真正把两段时间叠起来。判断依据很直接：测量一次同步迭代中 rollout 阶段与训练阶段的时长比，若 rollout 占比高且其内部呈长尾分布（少数样本耗时远超中位数），异步流水线的收益上界就由这个占比决定。</p>\n<p>第二刀是<b>偏差容忍度</b>。异步用样本滞后换时间重叠，代价是 off-policy 偏差；同族的批不变采样处理的是数值维度的批组成不变性，两者正交——前者管版本滞后，后者管批内一致性，可以叠加但不能互相替代。若任务对策略更新方向极其敏感（例如奖励稀疏、KL 约束本来就紧），异步的收益会被迫用更大的 $\\beta$ 换回来，此时应优先考虑同步或半同步折中。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-46\">四十六 · 决策表：六个判据与对应选择</h3>\n<p>把选择压缩成可执行的判据，比罗列算法名有用。下表按\"首要瓶颈 → 次要约束 → 推荐族\"组织，每行给出适用条件与不适用条件，工程上可直接对着 profiling 结果查表。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>首要瓶颈</th><th>次要约束</th><th>推荐算法族</th><th>不适用条件</th></tr>\n</thead>\n<tbody>\n<tr><td>训练步被 rollout 长尾阻塞</td><td>可容忍若干版本滞后</td><td>异步 Rollout 流水线（本条）</td><td>策略对陈旧度极敏感、$\\beta$ 无法调大</td></tr>\n<tr><td>KV 显存碎片、批组成频繁变化</td><td>需批不变语义</td><td>分页 KV 批量 Rollout + 批不变采样</td><td>序列极长、页表开销占比高</td></tr>\n<tr><td>预填算力与解码算力错配</td><td>长上下文占比高</td><td>预填解码分离 / 分块预填背驮解码</td><td>短序列为主，分离的通信开销吃掉收益</td></tr>\n<tr><td>多副本间 KV 复用率低</td><td>跨节点带宽充足</td><td>KV 中心分离式池化 / 前缀 KV 共享</td><td>前缀差异大、共享命中率低</td></tr>\n<tr><td>解码逐 token 成本高</td><td>有可用草稿模型</td><td>特征级投机采样 Rollout</td><td>草稿接受率低、验证开销反超</td></tr>\n<tr><td>样本质量参差、算力浪费在低价值样本</td><td>可在线评估</td><td>在线 Rollout 剪枝</td><td>剪枝判据本身昂贵、误杀高价值样本</td></tr>\n</tbody>\n</table>\n<p>表中每一行都不是互斥的：异步流水线常与分页 KV、前缀共享同栈部署，因为异步放大的是并发与队列深度，而队列深度直接抬高 KV 驻留压力。真正互斥的是语义层——批不变采样与在线剪枝都会改变\"哪些样本进入训练批\"，与异步的版本滞后叠加时，必须保证剪枝判据使用的是样本生成时的版本信息，否则版本标签与实际权重不符的失败模式会被剪枝放大。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-47\">四十七 · 定量判据：用公式把\"选不选异步\"算出来</h3>\n<p>同步与异步的取舍可以写成一条不等式。设一次同步迭代中 rollout 阶段耗时 $T_{\\text{rollout}}$、训练阶段耗时 $T_{\\text{train}}$，异步的重叠效率为 $\\text{overlap}\\in(0,1]$，则两条路径的吞吐比近似为：</p>\n<div class=\"formula\">$$\\frac{\\text{throughput}_{\\text{async}}}{\\text{throughput}_{\\text{sync}}}=\\frac{T_{\\text{rollout}}+T_{\\text{train}}}{T_{\\text{rollout}}/\\text{overlap}+T_{\\text{train}}}$$</div>\n<p>当 $\\text{overlap}\\to 1$ 且 $T_{\\text{rollout}}\\gg T_{\\text{train}}$ 时，比值趋近 $1+T_{\\text{rollout}}/T_{\\text{train}}$，这就是异步的理论上界；反之若 $T_{\\text{train}}$ 占主导，异步收益迅速衰减，因为训练侧本来就不是等待方。$\\text{overlap}$ 的现实上限由权重同步带宽与队列水位决定：同步通道每次推送全量权重，版本切换期间 rollout 引擎的并发会被原子切换打断，$\\text{overlap}$ 因此低于 1。工程上应把 $\\text{overlap}$ 实测为\"训练步执行期间 rollout 引擎仍在产出样本的时间占比\"，而不是假设它等于 1。</p>\n<p>偏差一侧的判据是陈旧度分布。核心信任域为 $r_k=\\left(\\pi_{\\theta}(x)/\\pi_{\\theta_{v-k}}(x)\\right)^{1/(1+\\beta k)}$，$\\beta$ 控制惩罚强度。选择时应保证队列中 $k$ 的高分位数（而非均值）落在可容忍区间：均值被大量新鲜样本拉低，长尾的旧样本才是震荡来源。若高分位 $k$ 对应的 $r_k$ 方差已经接近甚至超过同步情形下的重要性比方差，说明 $\\beta$ 不足或队列水位过高，此时应回退半同步（限制 $k\\le k_{\\max}$）而不是继续调大并发。这条判据把\"要不要异步\"变成两个可观测量：$\\text{overlap}$ 与 $k$ 的高分位数。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-48\">四十八 · 具体例子：一条长尾显著的 Agent rollout 如何选型</h3>\n<p>设某 Agent 任务的 rollout 是持续请求流，单条轨迹包含多轮工具调用，耗时分布长尾明显：多数轨迹在数百毫秒级完成，少数因外部工具等待拖到数秒。同步执行时，训练步必须等最后一条轨迹返回，GPU 在等待窗口空转，迭代 wall-clock 被采样阶段主导。此时按决策表首行，异步流水线是首选：rollout 引擎持续生成并写入带版本号的队列，训练侧按固定步频消费，长尾样本不再阻塞训练步。但这条轨迹的多轮结构意味着 KV 驻留时间长，队列深度一抬，KV 压力立刻上升——因此必须与分页 KV 批量 Rollout 同栈，否则异步带来的并发会先把显存打满，收益被 OOM 与重算吃掉。</p>\n<p>再看数值层：若该任务同时启用 NVFP4 量化以压低解码成本，量化误差与陈旧度偏差会叠加。量化稳定化处理的是数值精度，异步处理的是版本滞后，两者叠加时重要性比的方差会被放大，$\\beta$ 需要比纯 BF16 情形更保守。这是一个典型的\"算法可叠加但参数不可照搬\"的例子：决策表给的是族的选择，$\\beta$ 与 $k_{\\max}$ 必须按实际栈重新标定。若轨迹中存在大量共享系统提示与工具描述，前缀 KV 共享能把预填成本压下去，此时异步的队列可以更深而不显著抬高预填算力，$\\text{overlap}$ 的上界也随之抬高。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-49\">四十九 · 混合与回退：什么时候不该选异步</h3>\n<p>三类情形应明确排除异步。其一，训练阶段本身占主导（$T_{\\text{train}}&gt;T_{\\text{rollout}}$），此时重叠的分子收益小于队列与版本管理带来的系统复杂度，直接同步更稳。其二，策略改进方向对旧样本极敏感，例如 KL 惩罚系数本就很大、奖励信号稀疏，陈旧样本会把策略拉向旧版本方向，$\\beta$ 调大后又压制了新鲜样本的有效更新，形成\"异步但不改进\"的空转。其三，权重同步带宽不足：全量权重推送占用同步通道时间过长，版本切换频繁打断 rollout 并发，$\\text{overlap}$ 实测偏低，异步退化为\"带队列的同步\"，只剩复杂度没有收益。</p>\n<p>回退路径应设计成可切换的档位而非二选一。半同步是中间档：允许 $k\\le k_{\\max}$ 的样本进入训练批，超出则丢弃或降权，队列水位上限随之收紧。这与在线剪枝不同——剪枝按样本价值筛选，半同步按版本新鲜度筛选，判据正交，可同时启用但需保证剪枝发生在版本标签写入之后。另一条回退是缩短同步周期：把权重推送从\"每步\"改为\"每若干步\"，用更粗的版本粒度换取同步通道占用下降，代价是 $k$ 的分布整体右移，$\\beta$ 需同步上调。工程判断的落点在于：先测 $\\text{overlap}$ 与 $k$ 高分位，再决定档位，而不是先上异步再补正则。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-50\">五十 · 选型的工程落点：把判据写进调度器</h3>\n<p>决策表若只停留在文档里，部署时仍会退化成拍脑袋。可行的做法是把两个可观测量做成调度器的输入：$\\text{overlap}$ 由\"训练步执行窗口内 rollout 引擎的有效产出时间\"统计得到，$k$ 的高分位数由队列样本的版本标签与当前权重版本差实时计算。调度器据此在同步、半同步、全异步三档间切换，并联动调整 rollout 并发与训练步频——这正是队列水位与陈旧度分布反馈给调度器的机制，只是把\"调并发\"升级为\"调档位\"。当 $k$ 高分位越过阈值而 $\\beta$ 已接近上限时，降档比继续加正则更安全；当 $\\text{overlap}$ 因同步带宽下降而走低时，应先拉长权重推送周期而非缩小队列，因为后者会直接造成训练侧饥饿。</p>\n<p>最后一条判断落在版本原子性上。无论选哪一档，权重切换必须是原子的：rollout 引擎在切换瞬间混用新旧权重，会让队列中的版本标签与实际生成权重不符，此时任何基于 $k$ 的信任域缩放都建立在错误标签上，$\\beta$ 再大也约束不住方向失真。这是异步族相对其他族的额外系统代价，也是选型时必须计入的隐性成本——它不是算法参数问题，而是部署契约问题。</p>\n\n<h3 id=\"alg-async-rollout-pipeline-sec-51\">五十一 · 陈旧度信任域的边界：何时该退回同步</h3>\n<p>这套方案的有效性完全押在 $k$ 的分布上。信任域缩放 $r_k=(\\pi_\\theta/\\pi_{\\theta_{v-k}})^{1/(1+\\beta k)}$ 只在 $k$ 有界且 $\\beta$ 随 $k$ 同步上调时才成立；一旦队列积压使 $k$ 的长尾越过策略改进方向的可容忍偏差，过期样本就会把梯度拉回旧版本方向，表现为训练震荡而非收敛。此时唯一正确的动作是回退：要么把训练步频降到与 rollout 吞吐匹配、把 $k$ 压回小值，要么增大 $\\beta$ 让过期样本的权重趋近于零——后者等价于丢弃它们，只是保留了队列的连续性。判断阈值不是拍脑袋的，而是看陈旧度分布的分位数：当 $k$ 的高分位样本占比上升而 $\\beta$ 未动，失效已经在发生。</p>\n<p>与相邻算法的选择可以压成一张表。同步 RL 用串行换严格 on-policy，wall-clock 被长尾样本主导，适合样本短、方差小、对策略新鲜度极度敏感的场合；异步流水线用样本滞后换时间重叠，适合 rollout 长尾显著、采样阶段占训练 wall-clock 主导的场合；批不变采样处理的是数值维度的批组成偏差，与时间维度的版本滞后正交，二者可以叠加但不可互相替代。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>代价所在</th><th>失效条件</th><th>适用条件</th></tr></thead><tbody><tr><td>同步 RL</td><td>GPU 在长尾等待中空转</td><td>长尾占比高时利用率塌陷</td><td>样本短、策略新鲜度敏感</td></tr><tr><td>异步流水线</td><td>off-policy 偏差 + 版本管理复杂度</td><td>$k$ 越界且 $\\beta$ 未跟上</td><td>采样占主导、长尾显著</td></tr><tr><td>批不变采样</td><td>批组成偏差</td><td>批内长度方差过大</td><td>与时间维度问题正交</td></tr></tbody></table>\n<p>系统代价还有两条硬约束。其一，权重同步通道的带宽决定规模上限：版本切换越频繁，推送 $v+1$ 的开销越挤占 rollout 的有效吞吐，吞吐近似为 $N_{\\text{rollout}}/(T_{\\text{rollout}}/\\text{overlap}+T_{\\text{train}})$，同步开销藏在 overlap 项里，带宽不足时 overlap 收益被吃掉。其二，KV cache 随版本切换失效重建，切换瞬间队列里新旧版本样本混杂，若标签与实际生成权重不符，$k$ 的计算本身就是错的，信任域缩放失去意义。因此原子切换不是工程洁癖，而是公式成立的前提。</p>\n<p>工程判断落在反馈环的时滞上：队列水位与陈旧度分布反馈给调度器，但反馈滞后于训练步频变化时，rollout 并发与消费节奏失配，出现积压或训练侧饥饿空转。调度器必须以 $k$ 的分位数而非均值作为调节信号，因为均值会被大量新鲜样本掩盖长尾。当分位数持续抬升而调节无效，说明该规模已越过权重同步带宽或队列管理的承载边界，此时应缩小 rollout 并发、拉长训练步频，把系统拉回 $k$ 有界的工作点，而不是继续加并发赌吞吐。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · 批量生成调度与前缀共享</td></tr><tr><td>解决什么</td><td>同步RL中rollout与训练串行，rollout的长尾样本使GPU在等待中最久空转，训练迭代wall-clock被采…</td></tr><tr><td>一句话机制</td><td>rollout引擎持续生成、训练侧按固定节奏消费，允许样本滞后若干版本，用陈旧度自适应信任域约束更新幅度。</td></tr><tr><td>代价与失效</td><td>样本滞后引入off-policy偏差，陈旧度过大时策略改进方向失真，需额外正则；权重同步与队列管理增加系统复杂度，版本切换瞬间可能出现样本…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-async-rollout-pipeline · 共 8 个片段</p>\n";break;}}})();
